import {
    connectDatabase,
    disconnectDatabase,
} from "../src/config/database";

import {
    Types,
} from "mongoose";

import bcrypt from "bcryptjs";

import {
    Permission,
} from "../src/modules/permissions/permission.model";

import {
    Role,
} from "../src/modules/roles/role.model";

import {
    RolePermission,
} from "../src/modules/role-permissions/role.permission.model";

import {
    Owner,
} from "../src/modules/owners/owner.model";

import {
    User,
    type IUserDocument,
} from "../src/modules/users/user.model";

import {
    createUser,
} from "../src/modules/users/user.service";

import {
    seedNotificationTemplates,
} from "./seed-notification-templates";

import {
    Currency,
} from "../src/modules/currencies/currency.model";

/*
|--------------------------------------------------------------------------
| Configuration
|--------------------------------------------------------------------------
*/

const PASSWORD_SALT_ROUNDS = 12;

/*
|--------------------------------------------------------------------------
| System Permissions
|--------------------------------------------------------------------------
|
| IMPORTANT:
|
| Permission definitions do NOT automatically grant access.
|
| OWNER is unrestricted and does not depend on RolePermission.
|
| Every non-owner role receives permissions only when explicitly
| assigned by the OWNER.
|
|--------------------------------------------------------------------------
*/

const permissions = [
    // Attribute Management
    ["attributes", "read", "attributes.read"],
    ["attributes", "create", "attributes.create"],
    ["attributes", "update", "attributes.update"],
    ["attributes", "delete", "attributes.delete"],

    ["tickets", "read", "tickets.read"],
    ["tickets", "create", "tickets.create"],
    ["tickets", "update", "tickets.update"],
    ["tickets", "manage", "tickets.manage"],
    ["support", "read", "support.read"],
    ["support", "manage", "support.manage"],
    [
        "live-chat",
        "read",
        "live-chat.read",
    ],
    [
        "live-chat",
        "reply",
        "live-chat.reply",
    ],
    /*
    |--------------------------------------------------------------------------
    | Employee Management
    |--------------------------------------------------------------------------
    */

    [
        "employees",
        "read",
        "employees.read",
    ],

    [
        "employees",
        "create",
        "employees.create",
    ],

    [
        "employees",
        "update",
        "employees.update",
    ],

    [
        "employees",
        "delete",
        "employees.delete",
    ],

    [
        "employees",
        "manage",
        "employees.manage",
    ],

    /*
    |--------------------------------------------------------------------------
    | Employee Invitation Management
    |--------------------------------------------------------------------------
    */

    [
        "employee_invitations",
        "read",
        "employee_invitations.read",
    ],

    [
        "employee_invitations",
        "create",
        "employee_invitations.create",
    ],

    [
        "employee_invitations",
        "revoke",
        "employee_invitations.revoke",
    ],

    [
        "employee_invitations",
        "manage",
        "employee_invitations.manage",
    ],

    /*
    |--------------------------------------------------------------------------
    | Job Vacancy Management
    |--------------------------------------------------------------------------
    */

    [
        "job_vacancies",
        "read",
        "job_vacancies.read",
    ],

    [
        "job_vacancies",
        "create",
        "job_vacancies.create",
    ],

    [
        "job_vacancies",
        "update",
        "job_vacancies.update",
    ],

    [
        "job_vacancies",
        "delete",
        "job_vacancies.delete",
    ],

    [
        "job_vacancies",
        "manage",
        "job_vacancies.manage",
    ],

    /*
    |--------------------------------------------------------------------------
    | Job Application Management
    |--------------------------------------------------------------------------
    */

    [
        "job_applications",
        "read",
        "job_applications.read",
    ],

    [
        "job_applications",
        "update",
        "job_applications.update",
    ],

    [
        "job_applications",
        "approve",
        "job_applications.approve",
    ],

