/*
|--------------------------------------------------------------------------
| System Roles
|--------------------------------------------------------------------------
|
| No role automatically receives every permission.
|
|--------------------------------------------------------------------------
*/

const roles = [
    {
        name: "Super Administrator",
        slug: "super-admin",
        hierarchyLevel: 100,
        description:
            "Highest non-owner administrative role. Access is explicitly assigned by the OWNER.",
    },

    {
        name: "Administrator",
        slug: "admin",
        hierarchyLevel: 90,
        description:
            "Administrative access explicitly assigned by the OWNER.",
    },

    {
        name: "Manager",
        slug: "manager",
        hierarchyLevel: 70,
        description:
            "Management access explicitly assigned by the OWNER.",
    },

    {
        name: "Product Manager",
        slug: "product-manager",
        hierarchyLevel: 60,
        description:
            "Product management access explicitly assigned by the OWNER.",
    },

    {
        name: "Order Manager",
        slug: "order-manager",
        hierarchyLevel: 60,
        description:
            "Order management access explicitly assigned by the OWNER.",
    },

    {
        name: "Inventory Manager",
        slug: "inventory-manager",
        hierarchyLevel: 60,
        description:
            "Inventory management access explicitly assigned by the OWNER.",
    },

    {
        name: "Delivery Manager",
        slug: "delivery-manager",
        hierarchyLevel: 60,
        description:
            "Delivery management access explicitly assigned by the OWNER.",
    },

    {
        name: "Support",
        slug: "support",
        hierarchyLevel: 40,
        description:
            "Customer support access explicitly assigned by the OWNER.",
    },

    {
        name: "Rider",
        slug: "rider",
        hierarchyLevel: 20,
        description:
            "Rider administrative access explicitly assigned by the OWNER.",
    },
] as const;

/*
|--------------------------------------------------------------------------
| Seed System Permissions
|--------------------------------------------------------------------------
*/

const seedPermissions = async (): Promise<
    Map<string, Types.ObjectId>
> => {
    const permissionDocuments =
        new Map<
            string,
            Types.ObjectId
        >();

    for (const [
        resource,
        action,
        key,
    ] of permissions) {
        const permission =
            await Permission.findOneAndUpdate(
                {
                    key,
                },
                {
                    $set: {
                        resource,
                        action,
                        key,
                        description:
                            `${resource} ${action} permission.`,
                        isSystemPermission:
                            true,
                        status:
                            "ACTIVE",
                    },
                },
                {
                    upsert: true,
                    returnDocument:
                        "after",
                    setDefaultsOnInsert:
                        true,
                },
            )
                .select("_id")
                .exec();

        if (!permission) {
            throw new Error(
                `Failed to seed permission: ${key}`,
            );
        }

        permissionDocuments.set(
            key,
            permission._id,
        );
    }

    console.log(
        `System permissions seeded: ${permissionDocuments.size}`,
    );

    return permissionDocuments;
};

/*
|--------------------------------------------------------------------------
| Seed System Roles
|--------------------------------------------------------------------------
*/

const seedRoles = async (): Promise<
    Map<string, Types.ObjectId>
> => {
    const roleDocuments =
        new Map<
            string,
            Types.ObjectId
        >();

    for (const roleInput of roles) {
        const role =
            await Role.findOneAndUpdate(
                {
                    slug:
                        roleInput.slug,
                },
                {
                    $set: {
                        ...roleInput,

                        isSystemRole:
                            true,

                        status:
                            "ACTIVE",
                    },
                },
                {
                    upsert: true,
                    returnDocument:
                        "after",
                    setDefaultsOnInsert:
                        true,
                },
            )
                .select("_id")
                .exec();

        if (!role) {
            throw new Error(
                `Failed to seed role: ${roleInput.slug}`,
            );
        }

        roleDocuments.set(
            roleInput.slug,
            role._id,
        );
    }

    console.log(
        `System roles seeded: ${roleDocuments.size}`,
    );

    return roleDocuments;
};

/*
|--------------------------------------------------------------------------
| Seed Default Role Permissions
|--------------------------------------------------------------------------
|
| SECURITY RULE:
|
| There are NO automatic assignments.
|
| OWNER explicitly decides which permissions each role receives.
|
|--------------------------------------------------------------------------
*/

const seedRolePermissions = async (
    _permissionDocuments: Map<
        string,
        Types.ObjectId
    >,
    _roleDocuments: Map<
        string,
        Types.ObjectId
    >,
): Promise<void> => {
    console.log(
        "Role permissions seeded: 0 automatic assignments.",
    );

    console.log(
        "All non-owner permissions remain OWNER-controlled.",
    );
};

/*
|--------------------------------------------------------------------------
| Seed Owner
|--------------------------------------------------------------------------
*/

const seedOwner = async (): Promise<Types.ObjectId> => {
    const ownerName =
        process.env.OWNER_NAME
            ?.trim();

    const ownerEmail =
        process.env.OWNER_EMAIL
            ?.trim()
            .toLowerCase();

    const ownerPassword =
        process.env.OWNER_PASSWORD;

    const ownerCode =
        process.env.OWNER_CODE
            ?.trim();

    if (
        !ownerName ||
        !ownerEmail ||
        !ownerPassword ||
        !ownerCode
    ) {
        throw new Error(
            "OWNER_NAME, OWNER_EMAIL, OWNER_PASSWORD, and OWNER_CODE are required.",
        );
    }

    /*
    |--------------------------------------------------------------------------
    | Find Existing User
    |--------------------------------------------------------------------------
    */

    let ownerUser:
        | IUserDocument
        | null =
        await User.findOne({
            email:
                ownerEmail,
        })
            .select("+password")
            .exec();

    /*
    |--------------------------------------------------------------------------
    | Create Owner User
    |--------------------------------------------------------------------------
    */

    if (!ownerUser) {
        ownerUser =
            await createUser({
                name:
                    ownerName,

                email:
                    ownerEmail,

                password:
                    ownerPassword,
            });

        console.log(
            `Owner user created: ${ownerEmail}`,
        );
    }

    if (!ownerUser) {
        throw new Error(
            "Failed to create or retrieve owner user.",
        );
    }

    /*
    |--------------------------------------------------------------------------
    | Synchronize Owner Password
    |--------------------------------------------------------------------------
    */

    const passwordMatches =
        await bcrypt.compare(
            ownerPassword,
            ownerUser.password,
        );

    if (!passwordMatches) {
        ownerUser.password =
            await bcrypt.hash(
                ownerPassword,
                PASSWORD_SALT_ROUNDS,
            );

        ownerUser.passwordChangedAt =
            new Date();

        await ownerUser.save();

        console.log(
            `Owner password updated for ${ownerEmail}.`,
        );
    }

    /*
    |--------------------------------------------------------------------------
    | Check Existing Owner
    |--------------------------------------------------------------------------
    */

    const existingOwner =
        await Owner.findOne({
            userId:
                ownerUser._id,
        }).exec();

    if (existingOwner) {
        const secretCodeHash =
            await bcrypt.hash(
                ownerCode,
                PASSWORD_SALT_ROUNDS,
            );

        existingOwner.secretCodeHash =
            secretCodeHash;

        existingOwner.status =
            "ACTIVE";

        await existingOwner.save();

        console.log(
            "Owner account already exists; synchronized credentials and status.",
        );

        return ownerUser._id;
    }

    /*
    |--------------------------------------------------------------------------
    | Hash Owner Secret Code
    |--------------------------------------------------------------------------
    */

    const secretCodeHash =
        await bcrypt.hash(
            ownerCode,
            PASSWORD_SALT_ROUNDS,
        );

    /*
    |--------------------------------------------------------------------------
    | Create Owner Profile
    |--------------------------------------------------------------------------
    */

    await Owner.create({
        userId:
            ownerUser._id,

        role:
            "OWNER",

        secretCodeHash,

        status:
            "ACTIVE",
    });

    console.log(
        `Owner profile created for ${ownerEmail}.`,
    );

    return ownerUser._id;
};

/*
|--------------------------------------------------------------------------
| Main Seed
|--------------------------------------------------------------------------
*/

const seed = async (): Promise<void> => {
    await connectDatabase();

    // Ensure there is an ACTIVE default currency in the registry.
    // Keep an existing ACTIVE default; otherwise fall back to BDT.
    const activeDefaultCurrency = await Currency.exists({
        isDefault: true,
        status: "ACTIVE",
    });

    if (!activeDefaultCurrency) {
        await Currency.updateMany(
            { isDefault: true },
            { $set: { isDefault: false } },
        );

        await Currency.updateOne(
            { code: "BDT" },
            {
                $set: {
                    name: "Bangladeshi Taka",
                    symbol: "৳",
                    decimalPlaces: 2,
                    status: "ACTIVE",
                    isDefault: true,
                },
                $setOnInsert: {
                    code: "BDT",
                },
            },
            { upsert: true },
        );
    }

    // Synchronize currency display settings with the registry.
    // Existing monetary amounts are not converted.
    const seededDefaultCurrency = await Currency.findOne({
        isDefault: true,
        status: "ACTIVE",
    }).lean();

    if (seededDefaultCurrency) {
        const { Settings } = await import(
            "../src/modules/settings/settings.model"
        );

        await Settings.findOneAndUpdate(
            { category: "currency" },
            {
                $set: {
                    "values.defaultCurrency": seededDefaultCurrency.code,
                    "values.displaySymbol": seededDefaultCurrency.symbol,
                    "values.decimalPlaces": seededDefaultCurrency.decimalPlaces,
                },
            },
            { upsert: true, new: true, runValidators: true },
        );
    }

    console.log(
        "Starting NOPTRIX database seed...",
    );

    /*
    |--------------------------------------------------------------------------
    | Permission Catalog
    |--------------------------------------------------------------------------
    */

    const permissionDocuments =
        await seedPermissions();

    /*
    |--------------------------------------------------------------------------
    | System Roles
    |--------------------------------------------------------------------------
    */

    const roleDocuments =
        await seedRoles();

    /*
    |--------------------------------------------------------------------------
    | Explicit Role Permissions
    |--------------------------------------------------------------------------
    */

    await seedRolePermissions(
        permissionDocuments,
        roleDocuments,
    );

    /*
    |--------------------------------------------------------------------------
    | OWNER
    |--------------------------------------------------------------------------
    */

    const ownerUserId =
        await seedOwner();

    /*
    |--------------------------------------------------------------------------
    | Notification Templates
    |--------------------------------------------------------------------------
    |
    | 33 event keys × 4 channels = 132 templates.
    |
    |--------------------------------------------------------------------------
    */

    await seedNotificationTemplates(
        ownerUserId,
    );

    console.log(
        "NOPTRIX database seed completed successfully.",
    );
};

/*
|--------------------------------------------------------------------------
| Execute Seed
|--------------------------------------------------------------------------
*/

seed()
    .catch((error: unknown) => {
        console.error(
            "NOPTRIX seed failed.",
            error,
        );

        process.exitCode = 1;
    })
    .finally(
        async () => {
            await disconnectDatabase();
        },
    );

import {
    v2 as cloudinary,
    type ConfigOptions,
    type UploadApiResponse,
} from "cloudinary";

import { env } from "./env";
import { logger } from "../utils/logger";

/*
|--------------------------------------------------------------------------
| Cloudinary Configuration State
|--------------------------------------------------------------------------
*/

let isCloudinaryConfigured = false;
let isCloudinaryVerified = false;

/*
|--------------------------------------------------------------------------
| Cloudinary Configuration Type
|--------------------------------------------------------------------------
*/

export interface CloudinaryConfig {
    readonly cloudName: string;
    readonly apiKey: string;
    readonly secure: boolean;
}

/*
|--------------------------------------------------------------------------
| Check Cloudinary Configuration
|--------------------------------------------------------------------------
*/

const hasCloudinaryConfiguration = (): boolean => {
    return Boolean(
        env.CLOUDINARY_CLOUD_NAME &&
            env.CLOUDINARY_API_KEY &&
            env.CLOUDINARY_API_SECRET
    );
};

/*
|--------------------------------------------------------------------------
| Validate Cloudinary Environment
|--------------------------------------------------------------------------
*/

const validateCloudinaryEnvironment =
    (): void => {
        const values = [
            env.CLOUDINARY_CLOUD_NAME,
            env.CLOUDINARY_API_KEY,
            env.CLOUDINARY_API_SECRET,
        ];

        const configuredCount =
            values.filter(
                (value) =>
                    typeof value === "string" &&
                    value.trim().length > 0
            ).length;

        /*
        |--------------------------------------------------------------------------
        | Completely Disabled
        |--------------------------------------------------------------------------
        */

        if (configuredCount === 0) {
            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Partial Configuration
        |--------------------------------------------------------------------------
        */

        if (
            configuredCount !==
            values.length
        ) {
            throw new Error(
                "Incomplete Cloudinary configuration. CLOUDINARY_CLOUD_NAME, CLOUDINARY_API_KEY and CLOUDINARY_API_SECRET must all be provided."
            );
        }
    };

/*
|--------------------------------------------------------------------------
| Build Cloudinary Configuration
|--------------------------------------------------------------------------
*/

const buildCloudinaryConfig =
    (): CloudinaryConfig => {
        if (
            !env.CLOUDINARY_CLOUD_NAME ||
            !env.CLOUDINARY_API_KEY ||
            !env.CLOUDINARY_API_SECRET
        ) {
            throw new Error(
                "Cloudinary credentials are not configured."
            );
        }

        return Object.freeze({
            cloudName:
                env.CLOUDINARY_CLOUD_NAME,

            apiKey:
                env.CLOUDINARY_API_KEY,

            secure: true,
        });
    };

/*
|--------------------------------------------------------------------------
| Configure Cloudinary
|--------------------------------------------------------------------------
*/

export const configureCloudinary =
    (): void => {
        /*
        |--------------------------------------------------------------------------
        | Validate Environment
        |--------------------------------------------------------------------------
        */

        validateCloudinaryEnvironment();

        /*
        |--------------------------------------------------------------------------
        | Cloudinary Disabled
        |--------------------------------------------------------------------------
        */

        if (!hasCloudinaryConfiguration()) {
            isCloudinaryConfigured = false;
            isCloudinaryVerified = false;

            logger.warn(
                "Cloudinary is not configured. Cloud-based file operations are unavailable."
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Prevent Duplicate Configuration
        |--------------------------------------------------------------------------
        */

        if (isCloudinaryConfigured) {
            logger.debug(
                "Cloudinary is already configured."
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Build Configuration
        |--------------------------------------------------------------------------
        */

        const config =
            buildCloudinaryConfig();

        /*
        |--------------------------------------------------------------------------
        | Configure Cloudinary SDK
        |--------------------------------------------------------------------------
        */

        const sdkConfig: ConfigOptions = {
            cloud_name:
                config.cloudName,

            api_key:
                config.apiKey,

            api_secret:
                env.CLOUDINARY_API_SECRET,

            secure:
                config.secure,
        };

        cloudinary.config(
            sdkConfig
        );

        isCloudinaryConfigured = true;
        isCloudinaryVerified = false;

        logger.info(
            {
                cloudName:
                    config.cloudName,
                secure:
                    config.secure,
            },
            "Cloudinary SDK configured successfully."
        );
    };

/*
|--------------------------------------------------------------------------
| Get Cloudinary Client
|--------------------------------------------------------------------------
*/

export const getCloudinary = () => {
    if (!isCloudinaryConfigured) {
        throw new Error(
            "Cloudinary is not configured. Configure Cloudinary before using cloud services."
        );
    }

    return cloudinary;
};

/*
|--------------------------------------------------------------------------
| Verify Cloudinary Connection
|--------------------------------------------------------------------------
|
| This performs an authenticated API request.
|
|--------------------------------------------------------------------------
*/

export const verifyCloudinaryConnection =
    async (): Promise<boolean> => {
        if (!isCloudinaryConfigured) {
            logger.warn(
                "Cloudinary verification skipped because Cloudinary is not configured."
            );

            return false;
        }

        try {
            /*
            |--------------------------------------------------------------------------
            | Lightweight Authenticated Request
            |--------------------------------------------------------------------------
            */

            await cloudinary.api.ping();

            isCloudinaryVerified = true;

            logger.info(
                "Cloudinary connection verified successfully."
            );

            return true;
        } catch (error) {
            isCloudinaryVerified = false;

            logger.error(
                {
                    error,
                },
                "Cloudinary connection verification failed."
            );

            return false;
        }
    };

/*
|--------------------------------------------------------------------------
| Configuration Status
|--------------------------------------------------------------------------
*/

export const isCloudinaryConfiguredAndReady =
    (): boolean => {
        return (
            isCloudinaryConfigured &&
            isCloudinaryVerified
        );
    };

/*
|--------------------------------------------------------------------------
| Basic Configuration Status
|--------------------------------------------------------------------------
*/

export const isCloudinaryConfiguredStatus =
    (): boolean => {
        return isCloudinaryConfigured;
    };

/*
|--------------------------------------------------------------------------
| Health Status
|--------------------------------------------------------------------------
*/

export const isCloudinaryHealthy =
    (): boolean => {
        return (
            isCloudinaryConfigured &&
            isCloudinaryVerified
        );
    };

/*
|--------------------------------------------------------------------------
| Public Configuration Metadata
|--------------------------------------------------------------------------
|
| NEVER return API secret from here.
|
|--------------------------------------------------------------------------
*/

export const getCloudinaryPublicConfig =
    (): CloudinaryConfig | null => {
        if (!isCloudinaryConfigured) {
            return null;
        }

        return buildCloudinaryConfig();
    };

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    verifyAccessToken,
    type AccessTokenPayload,
} from "../utils/token";

/*
|--------------------------------------------------------------------------
| Admin Auth Context
|--------------------------------------------------------------------------
|
| Administrative authentication context.
|
| OWNER is intentionally supported here.
|
| Authorization hierarchy:
|
| OWNER
|   → Full A-Z system authority
|
| ADMIN / STAFF
|   → Role + explicitly assigned permissions
|
|--------------------------------------------------------------------------
*/

export interface AdminAuthContext {
    readonly adminId: string;

    readonly role?: string;

    readonly permissions: readonly string[];

    readonly secretVerified: boolean;

    readonly tokenIssuedAt?: number;

    readonly tokenExpiresAt?: number;

    readonly claims: Readonly<
        Record<string, unknown>
    >;
}

/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            adminAuth?: AdminAuthContext;
        }
    }
}

/*
|--------------------------------------------------------------------------
| Extract Bearer Token
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    authorizationHeader?: string
): string | null => {
    if (
        typeof authorizationHeader !==
        "string"
    ) {
        return null;
    }

    const normalized =
        authorizationHeader.trim();

    if (!normalized) {
        return null;
    }

    const parts =
        normalized.split(/\s+/);

    if (
        parts.length !== 2 ||
        parts[0]?.toLowerCase() !==
            "bearer"
    ) {
        return null;
    }

    const token =
        parts[1]?.trim();

    if (!token) {
        return null;
    }

    return token;
};

/*
|--------------------------------------------------------------------------
| Normalize Administrative Role
|--------------------------------------------------------------------------
*/

const normalizeAdminRole = (
    role: unknown
): string | undefined => {
    if (
        typeof role !== "string"
    ) {
        return undefined;
    }

    const normalized =
        role.trim().toUpperCase();

    return normalized || undefined;
};

/*
|--------------------------------------------------------------------------
| Normalize Permissions
|--------------------------------------------------------------------------
*/

const normalizeAdminPermissions = (
    permissions: unknown
): string[] => {
    if (!Array.isArray(permissions)) {
        return [];
    }

    return [
        ...new Set(
            permissions
                .filter(
                    (
                        permission
                    ): permission is string =>
                        typeof permission ===
                        "string"
                )
                .map((permission) =>
                    permission
                        .trim()
                        .toLowerCase()
                )
                .filter(Boolean)
        ),
    ];
};

/*
|--------------------------------------------------------------------------
| Build Admin Auth Context
|--------------------------------------------------------------------------
*/

export const buildAdminAuthContext = (
    payload: AccessTokenPayload
): AdminAuthContext => {
    const {
        sub,
        tokenType: _tokenType,
        iat,
        exp,
        ...additionalClaims
    } = payload;

    const claims =
        additionalClaims as Record<
            string,
            unknown
        >;

    const role =
        normalizeAdminRole(
            claims.role
        );

    const permissions =
        normalizeAdminPermissions(
            claims.permissions
        );

    const secretVerified =
        claims.secretVerified === true;

    return Object.freeze({
        adminId: sub,

        ...(role
            ? {
                  role,
              }
            : {}),

        permissions:
            Object.freeze([
                ...permissions,
            ]),

        secretVerified,

        ...(typeof iat === "number"
            ? {
                  tokenIssuedAt: iat,
              }
            : {}),

        ...(typeof exp === "number"
            ? {
                  tokenExpiresAt: exp,
              }
            : {}),

        claims:
            Object.freeze({
                ...claims,
            }),
    });
};

/*
|--------------------------------------------------------------------------
| Admin Authentication
|--------------------------------------------------------------------------
|
| Valid administrative access tokens are accepted here.
|
| OWNER is NOT rejected.
|
| OWNER must be allowed through the same authenticated
| administrative pipeline because OWNER is the highest
| administrative authority in NOPTRIX.
|
| Permission middleware will recognize OWNER and provide
| automatic full access.
|
|--------------------------------------------------------------------------
*/

export const adminAuth: RequestHandler = (
    req: Request,
    res: Response,
    next: NextFunction
) => {
    const token =
        extractBearerToken(
            req.headers.authorization
        );

    if (!token) {
        res.status(401).json({
            success: false,
            message:
                "Admin authentication required.",
        });

        return;
    }

    try {
        const payload =
            verifyAccessToken(token);

        /*
        |--------------------------------------------------------------------------
        | Access Token Validation
        |--------------------------------------------------------------------------
        */

        if (
            payload.tokenType !==
            "access"
        ) {
            res.status(401).json({
                success: false,
                message:
                    "Invalid admin authentication token.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Administrative Role Validation
        |--------------------------------------------------------------------------
        |
        | Normal customer/user tokens should not contain
        | an administrative role.
        |
        */

        const role =
            normalizeAdminRole(
                payload.role
            );

        if (!role) {
            res.status(403).json({
                success: false,
                message:
                    "Administrative role is required.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Build Administrative Context
        |--------------------------------------------------------------------------
        */

        req.adminAuth =
            buildAdminAuthContext(
                payload
            );

        next();
    } catch {
        res.status(401).json({
            success: false,
            message:
                "Invalid or expired admin authentication token.",
        });

        return;
    }
};

/*
|--------------------------------------------------------------------------
| Require Admin
|--------------------------------------------------------------------------
*/

export const requireAdmin: RequestHandler = (
    req,
    res,
    next
) => {
    if (!req.adminAuth?.adminId) {
        res.status(401).json({
            success: false,
            message:
                "Admin authentication required.",
        });

        return;
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Require Verified Admin
|--------------------------------------------------------------------------
*/

export const adminSecretVerified: RequestHandler = (
    req,
    res,
    next
) => {
    if (!req.adminAuth?.adminId) {
        res.status(401).json({
            success: false,
            message:
                "Admin authentication required.",
        });

        return;
    }

    if (
        req.adminAuth.secretVerified !==
        true
    ) {
        res.status(403).json({
            success: false,
            message:
                "Admin secret verification required.",
        });

        return;
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Require Owner
|--------------------------------------------------------------------------
|
| OWNER is identified by the immutable OWNER role.
|
|--------------------------------------------------------------------------
*/

export const requireOwnerAccess: RequestHandler = (
    req,
    res,
    next
) => {
    if (!req.adminAuth?.adminId) {
        res.status(401).json({
            success: false,
            message:
                "Admin authentication required.",
        });

        return;
    }

    if (
        req.adminAuth.role
            ?.trim()
            .toUpperCase() !==
        "OWNER"
    ) {
        res.status(403).json({
            success: false,
            message:
                "Owner access is required.",
        });

        return;
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Get Admin ID
|--------------------------------------------------------------------------
*/

export const getAuthenticatedAdminId = (
    req: Request
): string => {
    const adminId =
        req.adminAuth?.adminId;

    if (!adminId) {
        throw new Error(
            "Authenticated admin context is missing."
        );
    }

    return adminId;
};

/*
|--------------------------------------------------------------------------
| Backward-Compatible User ID Getter
|--------------------------------------------------------------------------
*/

export const getAuthenticatedUserId =
    getAuthenticatedAdminId;

/*
|--------------------------------------------------------------------------
| Get Admin Role
|--------------------------------------------------------------------------
*/

export const getAuthenticatedAdminRole = (
    req: Request
): string | undefined => {
    return req.adminAuth?.role;
};

/*
|--------------------------------------------------------------------------
| Get Admin Permissions
|--------------------------------------------------------------------------
*/

export const getAuthenticatedAdminPermissions = (
    req: Request
): readonly string[] => {
    return (
        req.adminAuth?.permissions ??
        []
    );
};

/*
|--------------------------------------------------------------------------
| Check Admin Authentication
|--------------------------------------------------------------------------
*/

export const isAdminAuthenticated = (
    req: Request
): boolean => {
    return Boolean(
        req.adminAuth?.adminId
    );
};

/*
|--------------------------------------------------------------------------
| Check Owner
|--------------------------------------------------------------------------
*/

export const isOwnerAuthenticated = (
    req: Request
): boolean => {
    return (
        req.adminAuth?.role
            ?.trim()
            .toUpperCase() ===
        "OWNER"
    );
};

/*
|--------------------------------------------------------------------------
| Check Secret Verification
|--------------------------------------------------------------------------
*/

export const isAdminSecretVerified = (
    req: Request
): boolean => {
    return (
        req.adminAuth
            ?.secretVerified === true
    );
};

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

/*
|--------------------------------------------------------------------------
| Audit Actions
|--------------------------------------------------------------------------
*/

export type AuditAction =
    | "CREATE"
    | "READ"
    | "UPDATE"
    | "DELETE"
    | "LOGIN"
    | "LOGOUT"
    | "REGISTER"
    | "VERIFY"
    | "APPROVE"
    | "REJECT"
    | "SUSPEND"
    | "ACTIVATE"
    | "UPLOAD"
    | "DOWNLOAD"
    | "EXPORT"
    | "IMPORT"
    | "PAYMENT"
    | "REFUND"
    | "CANCEL"
    | "OTHER";

/*
|--------------------------------------------------------------------------
| Audit Options
|--------------------------------------------------------------------------
*/

export interface AuditOptions {
    action: AuditAction;

    resource?: string;

    resourceId?:
        | string
        | ((
              req: Request
          ) => string | undefined);

    description?:
        | string
        | ((
              req: Request
          ) => string | undefined);

    metadata?:
        | Record<string, unknown>
        | ((
              req: Request
          ) => Record<string, unknown> | undefined);

    includeRequestBody?: boolean;

    includeQuery?: boolean;

    includeParams?: boolean;
}

/*
|--------------------------------------------------------------------------
| Audit Record
|--------------------------------------------------------------------------
*/

export interface AuditRecord {
    action: AuditAction;

    resource?: string;

    resourceId?: string;

    description?: string;

    userId?: string;

    tokenType?: string;

    method: string;

    path: string;

    ipAddress?: string;

    userAgent?: string;

    metadata?: Record<string, unknown>;

    requestBody?: unknown;

    query?: unknown;

    params?: unknown;

    timestamp: Date;
}

/*
|--------------------------------------------------------------------------
| Express Audit Context
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            audit?: {
                action: AuditAction;
                resource?: string;
                resourceId?: string;
            };
        }
    }
}

/*
|--------------------------------------------------------------------------
| Sensitive Fields
|--------------------------------------------------------------------------
*/

const SENSITIVE_FIELDS = new Set([
    "password",
    "currentPassword",
    "newPassword",
    "confirmPassword",

    "token",
    "accessToken",
    "refreshToken",

    "authorization",
    "cookie",

    "otp",
    "otpCode",
    "verificationCode",

    "secret",
    "secretCode",

    "apiKey",
    "apiSecret",

    "cardNumber",
    "cvv",
    "cvc",
]);

/*
|--------------------------------------------------------------------------
| Sanitize Value
|--------------------------------------------------------------------------
*/

const sanitizeValue = (
    value: unknown
): unknown => {
    if (value === null) {
        return null;
    }

    if (typeof value !== "object") {
        return value;
    }

    if (Array.isArray(value)) {
        return value.map(
            (item) => sanitizeValue(item)
        );
    }

    const object =
        value as Record<string, unknown>;

    const sanitized: Record<
        string,
        unknown
    > = {};

    for (const [
        key,
        currentValue,
    ] of Object.entries(object)) {
        if (
            SENSITIVE_FIELDS.has(
                key.toLowerCase()
            )
        ) {
            sanitized[key] = "[REDACTED]";
            continue;
        }

        sanitized[key] =
            sanitizeValue(currentValue);
    }

    return sanitized;
};

/*
|--------------------------------------------------------------------------
| Resolve Resource ID
|--------------------------------------------------------------------------
*/

const resolveResourceId = (
    req: Request,
    resourceId?:
        | string
        | ((
              req: Request
          ) => string | undefined)
): string | undefined => {
    if (typeof resourceId === "function") {
        return resourceId(req);
    }

    if (typeof resourceId === "string") {
        return resourceId;
    }

    const possibleIds = [
        "id",
        "userId",
        "adminId",
        "productId",
        "orderId",
        "customerId",
        "employeeId",
    ];

    for (const key of possibleIds) {
        const value = req.params?.[key];

        if (
            typeof value === "string" &&
            value.trim()
        ) {
            return value;
        }
    }

    return undefined;
};

/*
|--------------------------------------------------------------------------
| Resolve Description
|--------------------------------------------------------------------------
*/

const resolveDescription = (
    req: Request,
    description?:
        | string
        | ((
              req: Request
          ) => string | undefined)
): string | undefined => {
    if (typeof description === "function") {
        return description(req);
    }

    return description;
};

/*
|--------------------------------------------------------------------------
| Resolve Metadata
|--------------------------------------------------------------------------
*/

const resolveMetadata = (
    req: Request,
    metadata?:
        | Record<string, unknown>
        | ((
              req: Request
          ) => Record<string, unknown> | undefined)
): Record<string, unknown> | undefined => {
    if (typeof metadata === "function") {
        return metadata(req);
    }

    return metadata;
};

/*
|--------------------------------------------------------------------------
| Get IP Address
|--------------------------------------------------------------------------
*/

const getIpAddress = (
    req: Request
): string | undefined => {
    const forwardedFor =
        req.headers["x-forwarded-for"];

    if (typeof forwardedFor === "string") {
        return forwardedFor
            .split(",")[0]
            ?.trim();
    }

    if (Array.isArray(forwardedFor)) {
        return forwardedFor[0];
    }

    return (
        req.ip ||
        req.socket.remoteAddress ||
        undefined
    );
};

/*
|--------------------------------------------------------------------------
| Build Audit Record
|--------------------------------------------------------------------------
*/

const buildAuditRecord = (
    req: Request,
    options: AuditOptions
): AuditRecord => {
    const auditRecord: AuditRecord = {
        action: options.action,

        method: req.method,

        path: req.originalUrl || req.url,

        ipAddress: getIpAddress(req),

        userAgent:
            req.get("user-agent") ||
            undefined,

        timestamp: new Date(),
    };

    const resourceId =
        resolveResourceId(
            req,
            options.resourceId
        );

    if (options.resource) {
        auditRecord.resource =
            options.resource;
    }

    if (resourceId) {
        auditRecord.resourceId =
            resourceId;
    }

    const description =
        resolveDescription(
            req,
            options.description
        );

    if (description) {
        auditRecord.description =
            description;
    }

    const metadata =
        resolveMetadata(
            req,
            options.metadata
        );

    if (metadata) {
        auditRecord.metadata =
            sanitizeValue(
                metadata
            ) as Record<string, unknown>;
    }

    if (req.auth?.userId) {
        auditRecord.userId =
            req.auth.userId;
    }

    if (req.auth?.tokenType) {
        auditRecord.tokenType =
            req.auth.tokenType;
    }

    if (
        options.includeRequestBody &&
        req.body
    ) {
        auditRecord.requestBody =
            sanitizeValue(req.body);
    }

    if (
        options.includeQuery &&
        req.query
    ) {
        auditRecord.query =
            sanitizeValue(req.query);
    }

    if (
        options.includeParams &&
        req.params
    ) {
        auditRecord.params =
            sanitizeValue(req.params);
    }

    return auditRecord;
};

/*
|--------------------------------------------------------------------------
| Audit Sink
|--------------------------------------------------------------------------
*/

export type AuditSink = (
    record: AuditRecord
) => Promise<void> | void;

/*
|--------------------------------------------------------------------------
| Default Audit Sink
|--------------------------------------------------------------------------
*/

let auditSink: AuditSink = async (
    record
) => {
    if (
        process.env.NODE_ENV !==
        "production"
    ) {
        console.log(
            "[AUDIT]",
            JSON.stringify(
                record,
                null,
                2
            )
        );
    }
};

/*
|--------------------------------------------------------------------------
| Set Audit Sink
|--------------------------------------------------------------------------
*/

export const setAuditSink = (
    sink: AuditSink
): void => {
    auditSink = sink;
};

/*
|--------------------------------------------------------------------------
| Main Audit Middleware
|--------------------------------------------------------------------------
*/

export const auditMiddleware = (
    options: AuditOptions
): RequestHandler => {
    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        const resourceId =
            resolveResourceId(
                req,
                options.resourceId
            );

        req.audit = {
            action: options.action,

            ...(options.resource
                ? {
                      resource:
                          options.resource,
                  }
                : {}),

            ...(resourceId
                ? {
                      resourceId,
                  }
                : {}),
        };

        const auditRecord =
            buildAuditRecord(
                req,
                options
            );

        let finalized = false;

        const finalizeAudit =
            async (): Promise<void> => {
                if (finalized) {
                    return;
                }

                finalized = true;

                auditRecord.metadata = {
                    ...(auditRecord.metadata ??
                        {}),

                    responseStatus:
                        res.statusCode,

                    success:
                        res.statusCode < 400,
                };

                try {
                    await auditSink(
                        auditRecord
                    );
                } catch (
                    auditError
                ) {
                    if (
                        process.env
                            .NODE_ENV !==
                        "production"
                    ) {
                        console.error(
                            "[AUDIT_ERROR]",
                            auditError
                        );
                    }
                }
            };

        res.once(
            "finish",
            () => {
                void finalizeAudit();
            }
        );

        res.once(
            "close",
            () => {
                void finalizeAudit();
            }
        );

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Convenience Audit Middleware
|--------------------------------------------------------------------------
*/

export const audit = (
    action: AuditAction,
    options: Omit<
        AuditOptions,
        "action"
    > = {}
): RequestHandler => {
    return auditMiddleware({
        ...options,
        action,
    });
};

/*
|--------------------------------------------------------------------------
| Create Audit
|--------------------------------------------------------------------------
*/

export const auditCreate = (
    resource: string,
    options: Omit<
        AuditOptions,
        "action" | "resource"
    > = {}
): RequestHandler => {
    return auditMiddleware({
        ...options,
        action: "CREATE",
        resource,
    });
};

/*
|--------------------------------------------------------------------------
| Update Audit
|--------------------------------------------------------------------------
*/

export const auditUpdate = (
    resource: string,
    options: Omit<
        AuditOptions,
        "action" | "resource"
    > = {}
): RequestHandler => {
    return auditMiddleware({
        ...options,
        action: "UPDATE",
        resource,
    });
};

/*
|--------------------------------------------------------------------------
| Delete Audit
|--------------------------------------------------------------------------
*/

export const auditDelete = (
    resource: string,
    options: Omit<
        AuditOptions,
        "action" | "resource"
    > = {}
): RequestHandler => {
    return auditMiddleware({
        ...options,
        action: "DELETE",
        resource,
    });
};

/*
|--------------------------------------------------------------------------
| Login Audit
|--------------------------------------------------------------------------
*/

export const auditLogin = (
    resource = "AUTH",
    options: Omit<
        AuditOptions,
        "action" | "resource"
    > = {}
): RequestHandler => {
    return auditMiddleware({
        ...options,
        action: "LOGIN",
        resource,
    });
};

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    TOKEN_TYPES,
    type AccessTokenPayload,
    verifyAccessToken,
} from "../utils/token";

/*
|--------------------------------------------------------------------------
| Authenticated Request Context
|--------------------------------------------------------------------------
|
| This context becomes the foundation for:
|
| Auth
|   ↓
| Role
|   ↓
| Permission
|   ↓
| Resource Authorization
|
|--------------------------------------------------------------------------
*/

export interface AuthContext {
    readonly userId: string;
    readonly tokenType: typeof TOKEN_TYPES.ACCESS;
    readonly tokenIssuedAt?: number;
    readonly tokenExpiresAt?: number;
    readonly claims: Readonly<
        Record<string, unknown>
    >;
}

/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            auth?: AuthContext;
        }
    }
}

/*
|--------------------------------------------------------------------------
| Authorization Header Parser
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    authorizationHeader:
        | string
        | undefined
): string | null => {
    if (
        typeof authorizationHeader !==
        "string"
    ) {
        return null;
    }

    const normalized =
        authorizationHeader.trim();

    if (!normalized) {
        return null;
    }

    const parts =
        normalized.split(/\s+/);

    if (
        parts.length !== 2 ||
        parts[0].toLowerCase() !==
            "bearer"
    ) {
        return null;
    }

    const token =
        parts[1].trim();

    if (!token) {
        return null;
    }

    return token;
};

/*
|--------------------------------------------------------------------------
| Access Token Payload → Auth Context
|--------------------------------------------------------------------------
*/

const buildAuthContext = (
    payload: AccessTokenPayload
): AuthContext => {
    const {
        sub,
        tokenType,
        iat,
        exp,
        ...additionalClaims
    } = payload;

    return Object.freeze({
        userId: sub,
        tokenType,
        ...(typeof iat === "number"
            ? {
                  tokenIssuedAt: iat,
              }
            : {}),
        ...(typeof exp === "number"
            ? {
                  tokenExpiresAt: exp,
              }
            : {}),
        claims: Object.freeze({
            ...additionalClaims,
        }),
    });
};

/*
|--------------------------------------------------------------------------
| Authentication Middleware
|--------------------------------------------------------------------------
*/

export const authenticate: RequestHandler = (
    req: Request,
    res: Response,
    next: NextFunction
) => {
    const token =
        extractBearerToken(
            req.headers.authorization
        );

    /*
     * No token
     */
    if (!token) {
        res.status(401).json({
            success: false,
            message:
                "Authentication required.",
        });

        return;
    }

    try {
        /*
         * verifyAccessToken() already validates:
         *
         * - JWT signature
         * - HS256 algorithm
         * - expiration
         * - access token secret
         * - tokenType
         * - subject
         */
        const payload =
            verifyAccessToken(token);

        /*
         * Build a trusted request context.
         *
         * IMPORTANT:
         * Never use jwt.decode() or manually decoded
         * values for authorization.
         */
        req.auth =
            buildAuthContext(payload);

        next();
    } catch (error) {
        console.error(
            "USER AUTH TOKEN ERROR:",
            error instanceof Error
            ? error.message
            : error

        );
        /*
         * Do not expose JWT library internals.
         *
         * Examples:
         * - jwt expired
         * - invalid signature
         * - malformed token
         * - invalid algorithm
         *
         * All become the same external response.
         */
        res.status(401).json({
            success: false,
            message:
                "Invalid or expired authentication token.",
        });

        return;
    }
};

/*
|--------------------------------------------------------------------------
| Optional Authentication
|--------------------------------------------------------------------------
|
| Useful for endpoints such as:
|
| - public product details
| - public reviews
| - personalized recommendations
| - wishlist-aware product pages
|
| If a valid access token exists:
|     req.auth = ...
|
| If no/invalid token exists:
|     request continues as guest
|
*/

export const optionalAuthenticate: RequestHandler = (
    req: Request,
    _res: Response,
    next: NextFunction
) => {
    const token =
        extractBearerToken(
            req.headers.authorization
        );

    if (!token) {
        next();
        return;
    }

    try {
        const payload =
            verifyAccessToken(token);

        req.auth =
            buildAuthContext(payload);
    } catch {
        /*
         * Invalid optional authentication must not
         * automatically block a public endpoint.
         *
         * The route remains a guest request.
         */
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Require Authentication Helper
|--------------------------------------------------------------------------
|
| Useful when another middleware/controller needs
| to guarantee that authentication has already happened.
|
*/

export const requireAuthentication =
    (): RequestHandler => {
        return (
            req: Request,
            res: Response,
            next: NextFunction
        ) => {
            if (!req.auth) {
                res.status(401).json({
                    success: false,
                    message:
                        "Authentication required.",
                });

                return;
            }

            next();
        };
    };

/*
|--------------------------------------------------------------------------
| Auth Context Helpers
|--------------------------------------------------------------------------
*/

export const getAuthenticatedUserId = (
    req: Request
): string => {
    if (!req.auth?.userId) {
        throw new Error(
            "Authenticated user context is missing."
        );
    }

    return req.auth.userId;
};

/*
|--------------------------------------------------------------------------
| Authorization State Helper
|--------------------------------------------------------------------------
*/

export const isAuthenticated = (
    req: Request
): boolean => {
    return Boolean(req.auth);
};

import {
    Request,
    Response,
    NextFunction,
    ErrorRequestHandler,
} from "express";

import {
    ZodError,
} from "zod";

import {
    ApiError,
} from "../utils/ApiError";

/*
|--------------------------------------------------------------------------
| Error Response Shape
|--------------------------------------------------------------------------
*/

interface ErrorResponse {
    success: false;
    message: string;
    code?: string;
    errors?: unknown;
    stack?: string;
}

/*
|--------------------------------------------------------------------------
| HTTP Status Code Validation
|--------------------------------------------------------------------------
*/

const isValidStatusCode = (
    statusCode: unknown
): statusCode is number => {
    return (
        typeof statusCode === "number" &&
        Number.isInteger(statusCode) &&
        statusCode >= 400 &&
        statusCode <= 599
    );
};

/*
|--------------------------------------------------------------------------
| Error Message Extraction
|--------------------------------------------------------------------------
*/

const getErrorMessage = (
    error: unknown
): string => {
    if (
        error instanceof Error &&
        error.message.trim()
    ) {
        return error.message;
    }

    return "An unexpected error occurred.";
};

/*
|--------------------------------------------------------------------------
| Error Code Extraction
|--------------------------------------------------------------------------
*/

const getErrorCode = (
    error: unknown
): string | undefined => {
    if (
        typeof error === "object" &&
        error !== null &&
        "code" in error
    ) {
        const code =
            (
                error as {
                    code?: unknown;
                }
            ).code;

        if (
            typeof code === "string" &&
            code.trim()
        ) {
            return code;
        }
    }

    return undefined;
};

/*
|--------------------------------------------------------------------------
| ApiError Status Extraction
|--------------------------------------------------------------------------
*/

const getStatusCode = (
    error: unknown
): number => {
    if (
        error instanceof ApiError &&
        isValidStatusCode(
            error.statusCode
        )
    ) {
        return error.statusCode;
    }

    if (
        typeof error === "object" &&
        error !== null &&
        "statusCode" in error
    ) {
        const statusCode =
            (
                error as {
                    statusCode?: unknown;
                }
            ).statusCode;

        if (
            isValidStatusCode(
                statusCode
            )
        ) {
            return statusCode;
        }
    }

    if (
        typeof error === "object" &&
        error !== null &&
        "status" in error
    ) {
        const status =
            (
                error as {
                    status?: unknown;
                }
            ).status;

        if (
            isValidStatusCode(
                status
            )
        ) {
            return status;
        }
    }

    return 500;
};

/*
|--------------------------------------------------------------------------
| Development Environment Check
|--------------------------------------------------------------------------
*/

const isDevelopment =
    process.env.NODE_ENV !==
    "production";

/*
|--------------------------------------------------------------------------
| Zod Error Handler
|--------------------------------------------------------------------------
*/

const handleZodError = (
    error: ZodError
): ErrorResponse => {
    return {
        success: false,

        message:
            "Validation failed.",

        code:
            "VALIDATION_ERROR",

        errors:
            error.issues.map(
                (issue) => ({
                    field:
                        issue.path.join(
                            "."
                        ),

                    message:
                        issue.message,

                    code:
                        issue.code,
                })
            ),
    };
};

/*
|--------------------------------------------------------------------------
| Mongo / Mongoose Duplicate Key Error
|--------------------------------------------------------------------------
*/

const isDuplicateKeyError = (
    error: unknown
): boolean => {
    if (
        typeof error !== "object" ||
        error === null
    ) {
        return false;
    }

    if (
        "code" in error
    ) {
        const code =
            (
                error as {
                    code?: unknown;
                }
            ).code;

        return code === 11000;
    }

    return false;
};

/*
|--------------------------------------------------------------------------
| Duplicate Key Error Response
|--------------------------------------------------------------------------
*/

const handleDuplicateKeyError = (
    error: unknown
): ErrorResponse => {
    let message =
        "A record with the same unique value already exists.";

    let errors:
        | unknown
        | undefined;

    if (
        typeof error === "object" &&
        error !== null &&
        "keyValue" in error
    ) {
        const keyValue =
            (
                error as {
                    keyValue?: unknown;
                }
            ).keyValue;

        if (
            keyValue &&
            typeof keyValue ===
                "object"
        ) {
            const fields =
                Object.keys(
                    keyValue
                );

            if (
                fields.length > 0
            ) {
                message =
                    `A record with the same ${fields.join(
                        ", "
                    )} already exists.`;

                errors =
                    fields.map(
                        (
                            field
                        ) => ({
                            field,
                            message:
                                `${field} already exists.`,
                        })
                    );
            }
        }
    }

    return {
        success: false,
        message,
        code:
            "DUPLICATE_RESOURCE",
        ...(errors
            ? { errors }
            : {}),
    };
};

/*
|--------------------------------------------------------------------------
| Cast Error Handler
|--------------------------------------------------------------------------
|
| Handles invalid MongoDB ObjectId
| and similar cast failures.
|
|--------------------------------------------------------------------------
*/

const isMongooseCastError = (
    error: unknown
): boolean => {
    if (
        typeof error !== "object" ||
        error === null
    ) {
        return false;
    }

    if (
        "name" in error
    ) {
        const name =
            (
                error as {
                    name?: unknown;
                }
            ).name;

        return (
            name ===
            "CastError"
        );
    }

    return false;
};

const handleMongooseCastError =
    (): ErrorResponse => {
        return {
            success: false,

            message:
                "Invalid resource identifier.",

            code:
                "INVALID_RESOURCE_ID",
        };
    };

/*
|--------------------------------------------------------------------------
| Mongoose Validation Error
|--------------------------------------------------------------------------
*/

const isMongooseValidationError = (
    error: unknown
): boolean => {
    if (
        typeof error !== "object" ||
        error === null
    ) {
        return false;
    }

    if (
        "name" in error
    ) {
        const name =
            (
                error as {
                    name?: unknown;
                }
            ).name;

        return (
            name ===
            "ValidationError"
        );
    }

    return false;
};

const handleMongooseValidationError =
    (
        error: unknown
    ): ErrorResponse => {
        const errors: Array<{
            field: string;
            message: string;
        }> = [];

        if (
            typeof error ===
                "object" &&
            error !== null &&
            "errors" in error
        ) {
            const mongooseErrors =
                (
                    error as {
                        errors?: Record<
                            string,
                            {
                                message?: string;
                            }
                        >;
                    }
                ).errors;

            if (
                mongooseErrors
            ) {
                for (
                    const [
                        field,
                        fieldError,
                    ] of Object.entries(
                        mongooseErrors
                    )
                ) {
                    errors.push({
                        field,

                        message:
                            fieldError
                                ?.message ||
                            "Invalid value.",
                    });
                }
            }
        }

        return {
            success: false,

            message:
                "Database validation failed.",

            code:
                "DATABASE_VALIDATION_ERROR",

            ...(errors.length > 0
                ? { errors }
                : {}),
        };
    };

/*
|--------------------------------------------------------------------------
| JSON Parse Error
|--------------------------------------------------------------------------
*/

const isJsonParseError = (
    error: unknown
): boolean => {
    if (
        !(error instanceof Error)
    ) {
        return false;
    }

    return (
        error instanceof
            SyntaxError &&
        "body" in error
    );
};

const handleJsonParseError =
    (): ErrorResponse => {
        return {
            success: false,

            message:
                "Invalid JSON request body.",

            code:
                "INVALID_JSON",
        };
    };

/*
|--------------------------------------------------------------------------
| Error Logger
|--------------------------------------------------------------------------
*/

const logError = (
    error: unknown,
    req: Request
): void => {
    /*
     * Keep logging centralized.
     *
     * Later this can be connected directly
     * to the project's logger utility.
     */

    if (
        isDevelopment
    ) {
        console.error(
            "[ERROR]",
            {
                method:
                    req.method,

                path:
                    req.originalUrl,

                message:
                    getErrorMessage(
                        error
                    ),

                error,
            }
        );
    }
};

/*
|--------------------------------------------------------------------------
| Global Error Middleware
|--------------------------------------------------------------------------
*/

export const errorMiddleware:
    ErrorRequestHandler = (
        error,
        req,
        res,
        _next
    ) => {
        /*
        |--------------------------------------------------------------------------
        | Prevent duplicate responses
        |--------------------------------------------------------------------------
        */

        if (
            res.headersSent
        ) {
            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Logging
        |--------------------------------------------------------------------------
        */

        logError(
            error,
            req
        );

        /*
        |--------------------------------------------------------------------------
        | Zod Validation Error
        |--------------------------------------------------------------------------
        */

        if (
            error instanceof
            ZodError
        ) {
            const response =
                handleZodError(
                    error
                );

            res.status(
                400
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Duplicate Database Key
        |--------------------------------------------------------------------------
        */

        if (
            isDuplicateKeyError(
                error
            )
        ) {
            const response =
                handleDuplicateKeyError(
                    error
                );

            res.status(
                409
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Mongoose Cast Error
        |--------------------------------------------------------------------------
        */

        if (
            isMongooseCastError(
                error
            )
        ) {
            const response =
                handleMongooseCastError();

            res.status(
                400
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Mongoose Validation Error
        |--------------------------------------------------------------------------
        */

        if (
            isMongooseValidationError(
                error
            )
        ) {
            const response =
                handleMongooseValidationError(
                    error
                );

            res.status(
                400
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Invalid JSON
        |--------------------------------------------------------------------------
        */

        if (
            isJsonParseError(
                error
            )
        ) {
            const response =
                handleJsonParseError();

            res.status(
                400
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | ApiError
        |--------------------------------------------------------------------------
        */

        if (
            error instanceof
            ApiError
        ) {
            const statusCode =
                getStatusCode(
                    error
                );

            const response:
                ErrorResponse = {
                success: false,

                message:
                    error.message,

                ...(getErrorCode(
                    error
                )
                    ? {
                          code:
                              getErrorCode(
                                  error
                              ),
                      }
                    : {}),
            };

            /*
             * Expose stack only in development.
             */
            if (
                isDevelopment &&
                error.stack
            ) {
                response.stack =
                    error.stack;
            }

            res.status(
                statusCode
            ).json(
                response
            );

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Generic Error
        |--------------------------------------------------------------------------
        */

        const statusCode =
            getStatusCode(
                error
            );

        const response:
            ErrorResponse = {
            success: false,

            message:
                statusCode >= 500 &&
                !isDevelopment
                    ? "Internal server error."
                    : getErrorMessage(
                          error
                      ),
        };

        const errorCode =
            getErrorCode(
                error
            );

        if (
            errorCode
        ) {
            response.code =
                errorCode;
        }

        /*
         * Never expose stack traces
         * in production.
         */
        if (
            isDevelopment &&
            error instanceof Error &&
            error.stack
        ) {
            response.stack =
                error.stack;
        }

        res.status(
            statusCode
        ).json(
            response
        );
    };

/*
|--------------------------------------------------------------------------
| Alias
|--------------------------------------------------------------------------
|
| Some files may prefer the conventional
| "globalErrorHandler" naming.
|
|--------------------------------------------------------------------------
*/

export const globalErrorHandler =
    errorMiddleware;

/*
|--------------------------------------------------------------------------
| Not Found Handler
|--------------------------------------------------------------------------
*/

export const notFoundMiddleware =
    (
        req: Request,
        res: Response
    ): void => {
        res.status(404).json({
            success: false,

            message:
                `Route not found: ${req.method} ${req.originalUrl}`,

            code:
                "ROUTE_NOT_FOUND",
        });
    };

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    verifyAccessToken,
    type AccessTokenPayload,
} from "../utils/token";

/*
|--------------------------------------------------------------------------
| Owner Auth Context
|--------------------------------------------------------------------------
*/

export interface OwnerAuthContext {
    readonly ownerId: string;

    readonly userId: string;

    readonly sessionId?: string;

    readonly role: string;

    readonly secretVerified: boolean;

    readonly tokenIssuedAt?: number;

    readonly tokenExpiresAt?: number;

    readonly claims: Readonly<
        Record<string, unknown>
    >;
}

/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            ownerAuth?: OwnerAuthContext;
        }
    }
}

/*
|--------------------------------------------------------------------------
| Extract Bearer Token
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    authorizationHeader?: string
): string | null => {
    if (
        typeof authorizationHeader !==
        "string"
    ) {
        return null;
    }

    const normalized =
        authorizationHeader.trim();

    if (!normalized) {
        return null;
    }

    const parts =
        normalized.split(/\s+/);

    if (
        parts.length !== 2 ||
        parts[0].toLowerCase() !==
            "bearer"
    ) {
        return null;
    }

    const token =
        parts[1]?.trim();

    if (!token) {
        return null;
    }

    return token;
};

/*
|--------------------------------------------------------------------------
| Build Owner Auth Context
|--------------------------------------------------------------------------
*/

export const buildOwnerAuthContext = (
    payload: AccessTokenPayload
): OwnerAuthContext => {
    const {
        sub,
        tokenType,
        iat,
        exp,
        ...additionalClaims
    } = payload;

    const claims =
        additionalClaims as Record<
            string,
            unknown
        >;

    const role =
        typeof claims.role === "string"
            ? claims.role
            : "";

    const sessionId =
        typeof claims.sessionId === "string"
            ? claims.sessionId
            : undefined;

    const secretVerified =
        claims.secretVerified === true;

    return Object.freeze({
        ownerId: sub,
        userId: sub,
        sessionId,

        role,

        secretVerified,

        ...(typeof iat === "number"
            ? {
                  tokenIssuedAt: iat,
              }
            : {}),

        ...(typeof exp === "number"
            ? {
                  tokenExpiresAt: exp,
              }
            : {}),

        claims: Object.freeze({
            ...claims,
        }),
    });
};

/*
|--------------------------------------------------------------------------
| Owner Authentication
|--------------------------------------------------------------------------
*/

export const ownerAuth: RequestHandler = (
    req: Request,
    res: Response,
    next: NextFunction
) => {
    const token =
        extractBearerToken(
            req.headers.authorization
        );

    if (!token) {
        res.status(401).json({
            success: false,
            message:
                "Owner authentication required.",
        });

        return;
    }

    try {
        const payload =
            verifyAccessToken(token);

        /*
        |--------------------------------------------------------------------------
        | Token Type Validation
        |--------------------------------------------------------------------------
        */

        if (
            payload.tokenType !==
            "access"
        ) {
            res.status(401).json({
                success: false,
                message:
                    "Invalid owner authentication token.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Owner Role Validation
        |--------------------------------------------------------------------------
        */

        const role =
            typeof payload.role ===
            "string"
                ? payload.role
                : undefined;

        if (role !== "OWNER") {
            res.status(403).json({
                success: false,
                message:
                    "Owner access required.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Build Owner Context
        |--------------------------------------------------------------------------
        */

        req.ownerAuth =
            buildOwnerAuthContext(
                payload
            );

        next();
    } catch {
        res.status(401).json({
            success: false,
            message:
                "Invalid or expired owner authentication token.",
        });

        return;
    }
};

/*
|--------------------------------------------------------------------------
| Require Verified Owner
|--------------------------------------------------------------------------
*/

export const ownerSecretVerified: RequestHandler = (
    req,
    res,
    next
) => {
    if (!req.ownerAuth?.ownerId) {
        res.status(401).json({
            success: false,
            message:
                "Owner authentication required.",
        });

        return;
    }

    if (
        req.ownerAuth.secretVerified !==
        true
    ) {
        res.status(403).json({
            success: false,
            message:
                "Owner secret verification required.",
        });

        return;
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Get Authenticated Owner ID
|--------------------------------------------------------------------------
*/

export const getAuthenticatedOwnerId = (
    req: Request
): string => {
    const ownerId =
        req.ownerAuth?.ownerId;

    if (!ownerId) {
        throw new Error(
            "Authenticated owner context is missing."
        );
    }

    return ownerId;
};

