/*
|--------------------------------------------------------------------------
| Get Authenticated Owner User ID
|--------------------------------------------------------------------------
*/

export const getAuthenticatedOwnerUserId = (
    req: Request
): string => {
    const userId =
        req.ownerAuth?.userId;

    if (!userId) {
        throw new Error(
            "Authenticated owner user ID is missing."
        );
    }

    return userId;
};

/*
|--------------------------------------------------------------------------
| Get Owner Role
|--------------------------------------------------------------------------
*/

export const getAuthenticatedOwnerRole = (
    req: Request
): string | undefined => {
    return req.ownerAuth?.role;
};

/*
|--------------------------------------------------------------------------
| Check Owner Authentication
|--------------------------------------------------------------------------
*/

export const isOwnerAuthenticated = (
    req: Request
): boolean => {
    return Boolean(
        req.ownerAuth?.ownerId
    );
};

/*
|--------------------------------------------------------------------------
| Check Owner Secret Verification
|--------------------------------------------------------------------------
*/

export const isOwnerSecretVerified = (
    req: Request
): boolean => {
    return (
        req.ownerAuth
            ?.secretVerified === true
    );
};

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    Role,
} from "../modules/roles/role.model";

import {
    RolePermission,
} from "../modules/role-permissions/role.permission.model";

import {
    Permission,
} from "../modules/permissions/permission.model";

import {
    ApiError,
} from "../utils/ApiError";

/*
|--------------------------------------------------------------------------
| Permission Value
|--------------------------------------------------------------------------
*/

export type PermissionValue =
    | string
    | readonly string[];

/*
|--------------------------------------------------------------------------
| Express Request Permission Context
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            permissions?: readonly string[];
        }
    }
}

/*
|--------------------------------------------------------------------------
| Permission Normalizer
|--------------------------------------------------------------------------
*/

const normalizePermission = (
    permission: string
): string => {
    return permission
        .trim()
        .toLowerCase();
};

/*
|--------------------------------------------------------------------------
| Normalize Permissions
|--------------------------------------------------------------------------
*/

const normalizePermissions = (
    permissions: PermissionValue
): string[] => {
    const permissionList =
        Array.isArray(permissions)
            ? permissions
            : [permissions];

    return [
        ...new Set(
            permissionList
                .filter(
                    (
                        permission
                    ): permission is string =>
                        typeof permission ===
                        "string"
                )
                .map(
                    normalizePermission
                )
                .filter(Boolean)
        ),
    ];
};

/*
|--------------------------------------------------------------------------
| Check OWNER
|--------------------------------------------------------------------------
|
| OWNER is the root administrative authority.
|
| OWNER access must NEVER depend on the current list
| of permissions stored in the database.
|
| Therefore when a new permission is created tomorrow,
| OWNER automatically has access to it.
|
|--------------------------------------------------------------------------
*/

const isOwnerRequest = (
    req: Request
): boolean => {
    const role =
        req.adminAuth?.role;

    return (
        typeof role === "string" &&
        role.trim().toUpperCase() ===
            "OWNER"
    );
};

/*
|--------------------------------------------------------------------------
| Load Permissions From Database
|--------------------------------------------------------------------------
|
| Role
|   ↓
| RolePermission
|   ↓
| Permission
|   ↓
| permission.key
|
|--------------------------------------------------------------------------
*/

export const loadRolePermissions =
    async (
        roleId: string
    ): Promise<string[]> => {
        const role =
            await Role.findById(
                roleId
            )
                .select(
                    "_id status"
                )
                .lean()
                .exec();

        if (!role) {
            throw ApiError.notFound(
                "Role not found.",
                {
                    code:
                        "ROLE_NOT_FOUND",
                }
            );
        }

        if (
            role.status !==
            "ACTIVE"
        ) {
            throw ApiError.forbidden(
                "Role is inactive.",
                {
                    code:
                        "ROLE_INACTIVE",
                }
            );
        }

        const assignments =
            await RolePermission.find({
                roleId: role._id,
            })
                .select(
                    "permissionId"
                )
                .lean()
                .exec();

        if (
            assignments.length ===
            0
        ) {
            return [];
        }

        const permissionIds =
            assignments.map(
                (
                    assignment
                ) =>
                    assignment.permissionId
            );

        const permissions =
            await Permission.find({
                _id: {
                    $in:
                        permissionIds,
                },
                status:
                    "ACTIVE",
            })
                .select(
                    "key"
                )
                .lean()
                .exec();

        return [
            ...new Set(
                permissions
                    .map(
                        (
                            permission
                        ) =>
                            permission.key
                    )
                    .filter(Boolean)
                    .map(
                        normalizePermission
                    )
            ),
        ];
    };

/*
|--------------------------------------------------------------------------
| Get Request Permissions
|--------------------------------------------------------------------------
|
| OWNER receives an internal wildcard representation.
|
| Other administrative users receive only the permissions
| explicitly attached to their role.
|
| Normal authenticated users continue using req.permissions.
|
|--------------------------------------------------------------------------
*/

const getRequestPermissions = (
    req: Request
): string[] => {
    if (isOwnerRequest(req)) {
        return ["*"];
    }

    return normalizePermissions(
        req.permissions ?? []
    );
};

/*
|--------------------------------------------------------------------------
| Attach Permissions
|--------------------------------------------------------------------------
*/

export const attachPermissions = (
    permissions: PermissionValue
): RequestHandler => {
    return (
        req: Request,
        _res: Response,
        next: NextFunction
    ) => {
        const normalizedPermissions =
            normalizePermissions(
                permissions
            );

        req.permissions =
            Object.freeze([
                ...normalizedPermissions,
            ]);

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Require Authentication
|--------------------------------------------------------------------------
|
| Supports:
|
| req.adminAuth
| req.auth
|
|--------------------------------------------------------------------------
*/

const ensureAuthenticated = (
    req: Request,
    res: Response
): boolean => {
    if (
        !req.adminAuth &&
        !req.auth
    ) {
        res.status(401).json({
            success: false,
            message:
                "Authentication required.",
        });

        return false;
    }

    return true;
};

/*
|--------------------------------------------------------------------------
| Require Permission
|--------------------------------------------------------------------------
|
| ANY permission is enough.
|
|--------------------------------------------------------------------------
*/

export const requirePermission = (
    ...requiredPermissions: string[]
): RequestHandler => {
    const normalizedRequiredPermissions =
        normalizePermissions(
            requiredPermissions
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredPermissions.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid permission requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const userPermissions =
            getRequestPermissions(
                req
            );

        const hasPermission =
            normalizedRequiredPermissions.some(
                (permission) =>
                    userPermissions.includes(
                        permission
                    )
            );

        if (!hasPermission) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have permission to perform this action.",
            });

            return;
        }

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Require All Permissions
|--------------------------------------------------------------------------
*/

export const requireAllPermissions = (
    ...requiredPermissions: string[]
): RequestHandler => {
    const normalizedRequiredPermissions =
        normalizePermissions(
            requiredPermissions
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredPermissions.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid permission requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const userPermissions =
            getRequestPermissions(
                req
            );

        const hasAllPermissions =
            normalizedRequiredPermissions.every(
                (permission) =>
                    userPermissions.includes(
                        permission
                    )
            );

        if (!hasAllPermissions) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have all the required permissions.",
            });

            return;
        }

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Has Permission
|--------------------------------------------------------------------------
*/

export const hasPermission = (
    req: Request,
    permission: string
): boolean => {
    const normalizedPermission =
        normalizePermission(
            permission
        );

    if (!normalizedPermission) {
        return false;
    }

    /*
    |--------------------------------------------------------------------------
    | OWNER Full Access
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userPermissions =
        getRequestPermissions(
            req
        );

    return userPermissions.includes(
        normalizedPermission
    );
};

/*
|--------------------------------------------------------------------------
| Has Any Permission
|--------------------------------------------------------------------------
*/

export const hasAnyPermission = (
    req: Request,
    permissions: readonly string[]
): boolean => {
    /*
    |--------------------------------------------------------------------------
    | OWNER Full Access
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userPermissions =
        getRequestPermissions(
            req
        );

    const normalizedPermissions =
        normalizePermissions(
            permissions
        );

    if (
        normalizedPermissions.length ===
        0
    ) {
        return false;
    }

    return normalizedPermissions.some(
        (permission) =>
            userPermissions.includes(
                permission
            )
    );
};

/*
|--------------------------------------------------------------------------
| Has All Permissions
|--------------------------------------------------------------------------
*/

export const hasAllPermissions = (
    req: Request,
    permissions: readonly string[]
): boolean => {
    /*
    |--------------------------------------------------------------------------
    | OWNER Full Access
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userPermissions =
        getRequestPermissions(
            req
        );

    const normalizedPermissions =
        normalizePermissions(
            permissions
        );

    if (
        normalizedPermissions.length ===
        0
    ) {
        return false;
    }

    return normalizedPermissions.every(
        (permission) =>
            userPermissions.includes(
                permission
            )
    );
};

/*
|--------------------------------------------------------------------------
| Get Permissions
|--------------------------------------------------------------------------
*/

export const getPermissions = (
    req: Request
): readonly string[] => {
    return Object.freeze([
        ...getRequestPermissions(
            req
        ),
    ]);
};

/*
|--------------------------------------------------------------------------
| Permission Wildcards
|--------------------------------------------------------------------------
*/

const matchesPermission = (
    grantedPermission: string,
    requiredPermission: string
): boolean => {
    const granted =
        normalizePermission(
            grantedPermission
        );

    const required =
        normalizePermission(
            requiredPermission
        );

    if (
        !granted ||
        !required
    ) {
        return false;
    }

    /*
    |--------------------------------------------------------------------------
    | Full Wildcard
    |--------------------------------------------------------------------------
    */

    if (granted === "*") {
        return true;
    }

    /*
    |--------------------------------------------------------------------------
    | Exact Permission
    |--------------------------------------------------------------------------
    */

    if (granted === required) {
        return true;
    }

    /*
    |--------------------------------------------------------------------------
    | Resource Wildcard
    |--------------------------------------------------------------------------
    |
    | product.*
    | order.*
    | notification_templates.*
    |
    |--------------------------------------------------------------------------
    */

    if (
        granted.endsWith(".*")
    ) {
        const resource =
            granted.slice(
                0,
                -2
            );

        return (
            required === resource ||
            required.startsWith(
                `${resource}.`
            )
        );
    }

    return false;
};

/*
|--------------------------------------------------------------------------
| Has Permission With Wildcard Support
|--------------------------------------------------------------------------
*/

export const hasPermissionMatch = (
    req: Request,
    permission: string
): boolean => {
    const required =
        normalizePermission(
            permission
        );

    if (!required) {
        return false;
    }

    /*
    |--------------------------------------------------------------------------
    | OWNER Full Access
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userPermissions =
        getRequestPermissions(
            req
        );

    return userPermissions.some(
        (grantedPermission) =>
            matchesPermission(
                grantedPermission,
                required
            )
    );
};

/*
|--------------------------------------------------------------------------
| Require Permission Match
|--------------------------------------------------------------------------
*/

export const requirePermissionMatch = (
    ...requiredPermissions: string[]
): RequestHandler => {
    const normalizedRequiredPermissions =
        normalizePermissions(
            requiredPermissions
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredPermissions.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid permission requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const hasPermission =
            normalizedRequiredPermissions.some(
                (requiredPermission) =>
                    hasPermissionMatch(
                        req,
                        requiredPermission
                    )
            );

        if (!hasPermission) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have permission to perform this action.",
            });

            return;
        }

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Require All Permission Matches
|--------------------------------------------------------------------------
*/

export const requireAllPermissionMatches = (
    ...requiredPermissions: string[]
): RequestHandler => {
    const normalizedRequiredPermissions =
        normalizePermissions(
            requiredPermissions
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredPermissions.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid permission requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const hasAllPermissions =
            normalizedRequiredPermissions.every(
                (requiredPermission) =>
                    hasPermissionMatch(
                        req,
                        requiredPermission
                    )
            );

        if (!hasAllPermissions) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have all the required permissions.",
            });

            return;
        }

        next();
    };
};

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    verifyAccessToken,
    type AccessTokenPayload,
} from "../utils/token";


/*
|--------------------------------------------------------------------------
| Rider Auth Context
|--------------------------------------------------------------------------
*/

export interface RiderAuthContext {
    readonly riderId: string;

    readonly role?: string;

    readonly tokenIssuedAt?: number;

    readonly tokenExpiresAt?: number;

    readonly claims: Readonly<
        Record<string, unknown>
    >;
}


/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            riderAuth?: RiderAuthContext;
        }
    }
}


/*
|--------------------------------------------------------------------------
| Extract Bearer Token
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    authorizationHeader?: string
): string | null => {

    if (
        typeof authorizationHeader !==
        "string"
    ) {
        return null;
    }

    const normalized =
        authorizationHeader.trim();

    if (!normalized) {
        return null;
    }

    const parts =
        normalized.split(/\s+/);

    if (
        parts.length !== 2 ||
        parts[0].toLowerCase() !==
            "bearer"
    ) {
        return null;
    }

    const token =
        parts[1]?.trim();

    if (!token) {
        return null;
    }

    return token;
};


/*
|--------------------------------------------------------------------------
| Build Rider Auth Context
|--------------------------------------------------------------------------
*/

const buildRiderAuthContext = (
    payload: AccessTokenPayload
): RiderAuthContext => {

    const {
        sub,
        tokenType,
        iat,
        exp,
        ...additionalClaims
    } = payload;

    const claims =
        additionalClaims as Record<
            string,
            unknown
        >;

    const role =
        typeof claims.role === "string"
            ? claims.role
            : undefined;

    return Object.freeze({
        riderId: sub,

        ...(role
            ? {
                  role,
              }
            : {}),

        ...(typeof iat === "number"
            ? {
                  tokenIssuedAt: iat,
              }
            : {}),

        ...(typeof exp === "number"
            ? {
                  tokenExpiresAt: exp,
              }
            : {}),

        claims: Object.freeze({
            ...claims,
        }),
    });
};


/*
|--------------------------------------------------------------------------
| Rider Authentication
|--------------------------------------------------------------------------
*/

export const riderAuth: RequestHandler = (
    req: Request,
    res: Response,
    next: NextFunction
) => {

    const token =
        extractBearerToken(
            req.headers.authorization
        );

    if (!token) {
        res.status(401).json({
            success: false,

            message:
                "Rider authentication required.",
        });

        return;
    }

    try {

        const payload =
            verifyAccessToken(token);


        /*
        |--------------------------------------------------------------------------
        | Token Type Validation
        |--------------------------------------------------------------------------
        */

        if (
            payload.tokenType !==
            "access"
        ) {
            res.status(401).json({
                success: false,

                message:
                    "Invalid rider authentication token.",
            });

            return;
        }


        /*
        |--------------------------------------------------------------------------
        | Rider Role Validation
        |--------------------------------------------------------------------------
        */

        const role =
            payload.role;

        if (
            role !==
            "RIDER"
        ) {
            res.status(403).json({
                success: false,

                message:
                    "Rider access required.",
            });

            return;
        }


        /*
        |--------------------------------------------------------------------------
        | Rider ID Validation
        |--------------------------------------------------------------------------
        */

        if (
            typeof payload.sub !==
            "string" ||
            !payload.sub.trim()
        ) {
            res.status(401).json({
                success: false,

                message:
                    "Invalid rider authentication token.",
            });

            return;
        }


        /*
        |--------------------------------------------------------------------------
        | Build Rider Context
        |--------------------------------------------------------------------------
        */

        req.riderAuth =
            buildRiderAuthContext(
                payload
            );

        next();

    } catch {
        res.status(401).json({
            success: false,

            message:
                "Invalid or expired rider authentication token.",
        });

        return;
    }
};


/*
|--------------------------------------------------------------------------
| Require Rider
|--------------------------------------------------------------------------
*/

export const requireRider: RequestHandler = (
    req,
    res,
    next
) => {

    if (
        !req.riderAuth?.riderId
    ) {
        res.status(401).json({
            success: false,

            message:
                "Rider authentication required.",
        });

        return;
    }

    next();
};


/*
|--------------------------------------------------------------------------
| Require Rider Role
|--------------------------------------------------------------------------
*/

export const requireRiderRole: RequestHandler = (
    req,
    res,
    next
) => {

    if (
        !req.riderAuth?.riderId
    ) {
        res.status(401).json({
            success: false,

            message:
                "Rider authentication required.",
        });

        return;
    }

    if (
        req.riderAuth.role !==
        "RIDER"
    ) {
        res.status(403).json({
            success: false,

            message:
                "Rider access required.",
        });

        return;
    }

    next();
};


/*
|--------------------------------------------------------------------------
| Get Authenticated Rider ID
|--------------------------------------------------------------------------
*/

export const getAuthenticatedRiderId = (
    req: Request
): string => {

    const riderId =
        req.riderAuth?.riderId;

    if (!riderId) {
        throw new Error(
            "Authenticated rider context is missing."
        );
    }

    return riderId;
};


/*
|--------------------------------------------------------------------------
| Get Rider Role
|--------------------------------------------------------------------------
*/

export const getAuthenticatedRiderRole = (
    req: Request
): string | undefined => {

    return req.riderAuth?.role;
};


/*
|--------------------------------------------------------------------------
| Check Rider Authentication
|--------------------------------------------------------------------------
*/

export const isRiderAuthenticated = (
    req: Request
): boolean => {

    return Boolean(
        req.riderAuth?.riderId
    );
};

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

/*
|--------------------------------------------------------------------------
| Role Value
|--------------------------------------------------------------------------
*/

export type RoleValue =
    | string
    | readonly string[];

/*
|--------------------------------------------------------------------------
| Express Request Role Context
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            role?: string;
            roles?: readonly string[];
        }
    }
}

/*
|--------------------------------------------------------------------------
| Normalize Role
|--------------------------------------------------------------------------
*/

const normalizeRole = (
    role: string
): string => {
    return role
        .trim()
        .toUpperCase();
};

/*
|--------------------------------------------------------------------------
| Normalize Roles
|--------------------------------------------------------------------------
*/

const normalizeRoles = (
    roles: RoleValue
): string[] => {
    const roleList =
        Array.isArray(roles)
            ? roles
            : [roles];

    return [
        ...new Set(
            roleList
                .filter(
                    (
                        role
                    ): role is string =>
                        typeof role ===
                        "string"
                )
                .map(normalizeRole)
                .filter(Boolean)
        ),
    ];
};

/*
|--------------------------------------------------------------------------
| Check OWNER
|--------------------------------------------------------------------------
|
| Only an authenticated administrative OWNER receives
| the root-level role bypass.
|
| Normal USER auth context can never activate this.
|
|--------------------------------------------------------------------------
*/

const isOwnerRequest = (
    req: Request
): boolean => {
    const role =
        req.adminAuth?.role;

    return (
        typeof role === "string" &&
        role.trim().toUpperCase() ===
            "OWNER"
    );
};

/*
|--------------------------------------------------------------------------
| Get Request Roles
|--------------------------------------------------------------------------
|
| Priority:
|
| 1. Explicit req.roles
| 2. Explicit req.role
| 3. Administrative role from req.adminAuth
|
|--------------------------------------------------------------------------
*/

const getRequestRoles = (
    req: Request
): string[] => {
    if (
        Array.isArray(req.roles) &&
        req.roles.length > 0
    ) {
        return normalizeRoles(
            req.roles
        );
    }

    if (
        typeof req.role ===
        "string" &&
        req.role.trim()
    ) {
        return normalizeRoles(
            req.role
        );
    }

    if (
        typeof req.adminAuth?.role ===
        "string"
    ) {
        return normalizeRoles(
            req.adminAuth.role
        );
    }

    return [];
};

/*
|--------------------------------------------------------------------------
| Attach Roles
|--------------------------------------------------------------------------
*/

export const attachRoles = (
    roles: RoleValue
): RequestHandler => {
    return (
        req: Request,
        _res: Response,
        next: NextFunction
    ) => {
        const normalizedRoles =
            normalizeRoles(roles);

        req.roles =
            Object.freeze([
                ...normalizedRoles,
            ]);

        req.role =
            normalizedRoles[0];

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Require Authentication
|--------------------------------------------------------------------------
|
| Supports both:
|
| req.adminAuth
| req.auth
|
|--------------------------------------------------------------------------
*/

const ensureAuthenticated = (
    req: Request,
    res: Response
): boolean => {
    if (
        !req.adminAuth &&
        !req.auth
    ) {
        res.status(401).json({
            success: false,
            message:
                "Authentication required.",
        });

        return false;
    }

    return true;
};

/*
|--------------------------------------------------------------------------
| Require At Least One Role
|--------------------------------------------------------------------------
*/

export const requireRole = (
    ...requiredRoles: string[]
): RequestHandler => {
    const normalizedRequiredRoles =
        normalizeRoles(
            requiredRoles
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredRoles.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid role requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Role Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const userRoles =
            getRequestRoles(req);

        const hasRequiredRole =
            normalizedRequiredRoles.some(
                (requiredRole) =>
                    userRoles.includes(
                        requiredRole
                    )
            );

        if (!hasRequiredRole) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have permission to access this resource.",
            });

            return;
        }

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Require All Roles
|--------------------------------------------------------------------------
*/

export const requireAllRoles = (
    ...requiredRoles: string[]
): RequestHandler => {
    const normalizedRequiredRoles =
        normalizeRoles(
            requiredRoles
        );

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            normalizedRequiredRoles.length ===
            0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid role requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Role Access
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const userRoles =
            getRequestRoles(req);

        const hasAllRequiredRoles =
            normalizedRequiredRoles.every(
                (requiredRole) =>
                    userRoles.includes(
                        requiredRole
                    )
            );

        if (!hasAllRequiredRoles) {
            res.status(403).json({
                success: false,
                message:
                    "You do not have all the required roles.",
            });

            return;
        }

        next();
    };
};

/*
|--------------------------------------------------------------------------
| Has Role
|--------------------------------------------------------------------------
*/

export const hasRole = (
    req: Request,
    role: string
): boolean => {
    const normalizedRole =
        normalizeRole(role);

    if (!normalizedRole) {
        return false;
    }

    /*
    |--------------------------------------------------------------------------
    | OWNER Full Role Authority
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userRoles =
        getRequestRoles(req);

    return userRoles.includes(
        normalizedRole
    );
};

/*
|--------------------------------------------------------------------------
| Has Any Role
|--------------------------------------------------------------------------
*/

export const hasAnyRole = (
    req: Request,
    roles: readonly string[]
): boolean => {
    /*
    |--------------------------------------------------------------------------
    | OWNER Full Role Authority
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userRoles =
        getRequestRoles(req);

    const normalizedRoles =
        normalizeRoles(roles);

    if (
        normalizedRoles.length ===
        0
    ) {
        return false;
    }

    return normalizedRoles.some(
        (role) =>
            userRoles.includes(
                role
            )
    );
};

/*
|--------------------------------------------------------------------------
| Has All Roles
|--------------------------------------------------------------------------
*/

export const hasAllRoles = (
    req: Request,
    roles: readonly string[]
): boolean => {
    /*
    |--------------------------------------------------------------------------
    | OWNER Full Role Authority
    |--------------------------------------------------------------------------
    */

    if (isOwnerRequest(req)) {
        return true;
    }

    const userRoles =
        getRequestRoles(req);

    const normalizedRoles =
        normalizeRoles(roles);

    if (
        normalizedRoles.length ===
        0
    ) {
        return false;
    }

    return normalizedRoles.every(
        (role) =>
            userRoles.includes(
                role
            )
    );
};

/*
|--------------------------------------------------------------------------
| Get Primary Role
|--------------------------------------------------------------------------
*/

export const getPrimaryRole = (
    req: Request
): string | null => {
    const roles =
        getRequestRoles(req);

    return roles[0] ?? null;
};

/*
|--------------------------------------------------------------------------
| Get All Roles
|--------------------------------------------------------------------------
*/

export const getRoles = (
    req: Request
): readonly string[] => {
    /*
    |--------------------------------------------------------------------------
    | OWNER
    |--------------------------------------------------------------------------
    |
    | OWNER is not represented as every possible role.
    | The immutable OWNER identity remains the primary role.
    |
    |--------------------------------------------------------------------------
    */

    return Object.freeze([
        ...getRequestRoles(req),
    ]);
};

/*
|--------------------------------------------------------------------------
| Role Guard Factory
|--------------------------------------------------------------------------
*/

export const createRoleGuard = (
    options: {
        anyOf?: readonly string[];
        allOf?: readonly string[];
    }
): RequestHandler => {
    const anyOf =
        options.anyOf
            ? normalizeRoles(
                  options.anyOf
              )
            : [];

    const allOf =
        options.allOf
            ? normalizeRoles(
                  options.allOf
              )
            : [];

    return (
        req: Request,
        res: Response,
        next: NextFunction
    ) => {
        if (
            !ensureAuthenticated(
                req,
                res
            )
        ) {
            return;
        }

        if (
            anyOf.length === 0 &&
            allOf.length === 0
        ) {
            res.status(403).json({
                success: false,
                message:
                    "No valid role requirement was provided.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | OWNER Full Role Authority
        |--------------------------------------------------------------------------
        */

        if (isOwnerRequest(req)) {
            next();
            return;
        }

        const userRoles =
            getRequestRoles(req);

        /*
        |--------------------------------------------------------------------------
        | ANY Rule
        |--------------------------------------------------------------------------
        */

        if (
            anyOf.length > 0 &&
            !anyOf.some(
                (role) =>
                    userRoles.includes(
                        role
                    )
            )
        ) {
            res.status(403).json({
                success: false,
                message:
                    "Required role was not found.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | ALL Rule
        |--------------------------------------------------------------------------
        */

        if (
            allOf.length > 0 &&
            !allOf.every(
                (role) =>
                    userRoles.includes(
                        role
                    )
            )
        ) {
            res.status(403).json({
                success: false,
                message:
                    "Required roles were not found.",
            });

            return;
        }

        next();
    };
};

import {
    Request,
    Response,
    NextFunction,
} from "express";

import {
    verifyAccessToken,
} from "../utils/token";

import {
    ApiError,
} from "../utils/ApiError";


/*
|--------------------------------------------------------------------------
| Seller Auth Context
|--------------------------------------------------------------------------
*/

export interface SellerAuthContext {
    readonly sellerId: string;
    readonly role?: string;
    readonly tokenIssuedAt?: number;
    readonly tokenExpiresAt?: number;
    readonly claims: Readonly<
        Record<string, unknown>
    >;
}


/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            sellerAuth?:
                SellerAuthContext;
        }
    }
}


/*
|--------------------------------------------------------------------------
| Extract Bearer Token
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    req: Request
): string | null => {

    const authorization =
        req.headers.authorization;

    if (
        !authorization ||
        typeof authorization !==
            "string"
    ) {
        return null;
    }

    const [
        scheme,
        token,
    ] =
        authorization.trim().split(
            /\s+/
        );

    if (
        scheme?.toLowerCase() !==
            "bearer" ||
        !token
    ) {
        return null;
    }

    return token;
};


/*
|--------------------------------------------------------------------------
| Build Seller Auth Context
|--------------------------------------------------------------------------
*/

const buildSellerAuthContext = (
    payload: Record<string, unknown>
): SellerAuthContext => {

    const sellerId =
        typeof payload.sub ===
        "string"
            ? payload.sub
            : "";

    if (!sellerId) {
        throw ApiError.unauthorized(
            "Seller token subject is missing.",
            {
                code:
                    "SELLER_TOKEN_SUBJECT_MISSING",
            }
        );
    }


    return {
        sellerId,

        role:
            typeof payload.role ===
            "string"
                ? payload.role
                : undefined,

        tokenIssuedAt:
            typeof payload.iat ===
            "number"
                ? payload.iat
                : undefined,

        tokenExpiresAt:
            typeof payload.exp ===
            "number"
                ? payload.exp
                : undefined,

        claims:
            payload as Readonly<
                Record<string, unknown>
            >,
    };
};


/*
|--------------------------------------------------------------------------
| Seller Authentication Middleware
|--------------------------------------------------------------------------
*/

export const sellerAuth = (
    req: Request,
    _res: Response,
    next: NextFunction
): void => {

    try {

        const token =
            extractBearerToken(req);


        if (!token) {
            throw ApiError.unauthorized(
                "Seller authentication required.",
                {
                    code:
                        "SELLER_AUTH_REQUIRED",
                }
            );
        }


        const payload =
            verifyAccessToken(
                token
            );


        /*
        |--------------------------------------------------------------------------
        | Token Type
        |--------------------------------------------------------------------------
        */

        if (
            payload.tokenType !==
            "access"
        ) {
            throw ApiError.unauthorized(
                "Invalid seller access token.",
                {
                    code:
                        "INVALID_TOKEN_TYPE",
                }
            );
        }


        /*
        |--------------------------------------------------------------------------
        | Seller Role
        |--------------------------------------------------------------------------
        */

        if (
            payload.role !==
            "SELLER"
        ) {
            throw ApiError.forbidden(
                "Seller access required.",
                {
                    code:
                        "SELLER_ROLE_REQUIRED",
                }
            );
        }


        /*
        |--------------------------------------------------------------------------
        | Seller ID
        |--------------------------------------------------------------------------
        */

        if (
            typeof payload.sub !==
                "string" ||
            !payload.sub.trim()
        ) {
            throw ApiError.unauthorized(
                "Seller token subject is invalid.",
                {
                    code:
                        "INVALID_SELLER_SUBJECT",
                }
            );
        }


        req.sellerAuth =
            buildSellerAuthContext(
                payload as Record<
                    string,
                    unknown
                >
            );


        next();

    } catch (error) {
        next(error);
    }
};


