/*
|--------------------------------------------------------------------------
| Validate Uploaded File
|--------------------------------------------------------------------------
*/

export const requireUploadedFile =
    (
        fieldName = "file"
    ): RequestHandler => {
        return (
            req: Request,
            res: Response,
            next: NextFunction
        ) => {
            const file =
                req.file;

            if (!file) {
                res.status(400).json({
                    success: false,
                    message:
                        `No file was uploaded in "${fieldName}".`,
                });

                return;
            }

            next();
        };
    };

/*
|--------------------------------------------------------------------------
| Validate Uploaded Files
|--------------------------------------------------------------------------
*/
export const uploadErrorHandler =
    (
        error: unknown,
        _req: Request,
        res: Response,
        next: NextFunction
    ): void => {
        /*
        |--------------------------------------------------------------------------
        | Custom Upload Error
        |--------------------------------------------------------------------------
        */

        if (
            error instanceof UploadError
        ) {
            res.status(
                error.statusCode
            ).json({
                success: false,
                message:
                    error.message,
                code:
                    error.code,
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Multer Error
        |--------------------------------------------------------------------------
        */

        if (
            error instanceof
            multer.MulterError
        ) {
            const errorCode =
                String(
                    error.code
                );

            let message =
                "File upload failed.";

            switch (
                errorCode
            ) {
                case "LIMIT_FILE_SIZE":
                    message =
                        "Uploaded file is too large.";
                    break;

                case "LIMIT_FILE_COUNT":
                    message =
                        "Too many files were uploaded.";
                    break;

                case "LIMIT_UNEXPECTED_FILE":
                    message =
                        "Unexpected file field.";
                    break;

                case "LIMIT_PART_COUNT":
                    message =
                        "Too many multipart form parts.";
                    break;

                case "LIMIT_FIELD_COUNT":
                    message =
                        "Too many form fields.";
                    break;

                case "LIMIT_FIELD_KEY":
                    message =
                        "Uploaded field name is too long.";
                    break;

                case "LIMIT_FIELD_VALUE":
                    message =
                        "Uploaded field value is too large.";
                    break;

                default:
                    message =
                        error.message ||
                        message;
                    break;
            }

            res.status(400).json({
                success: false,
                message,
                code:
                    errorCode,
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Unknown Error
        |--------------------------------------------------------------------------
        |
        | Forward unknown errors to the global error middleware.
        |
        */

        next(error);
    };

import {
    Request,
    Response,
    NextFunction,
    RequestHandler,
} from "express";

import {
    verifyAccessToken,
    type AccessTokenPayload,
} from "../utils/token";

/*
|--------------------------------------------------------------------------
| User Auth Context
|--------------------------------------------------------------------------
*/

export interface UserAuthContext {
    readonly userId: string;

    readonly tokenIssuedAt?: number;

    readonly tokenExpiresAt?: number;

    readonly claims: Readonly<
        Record<string, unknown>
    >;
}

/*
|--------------------------------------------------------------------------
| Express Request Extension
|--------------------------------------------------------------------------
*/

declare global {
    namespace Express {
        interface Request {
            userAuth?: UserAuthContext;
        }
    }
}

/*
|--------------------------------------------------------------------------
| Extract Bearer Token
|--------------------------------------------------------------------------
*/

const extractBearerToken = (
    authorizationHeader?: string
): string | null => {
    if (
        typeof authorizationHeader !==
        "string"
    ) {
        return null;
    }

    const normalized =
        authorizationHeader.trim();

    if (!normalized) {
        return null;
    }

    const parts =
        normalized.split(/\s+/);

    if (
        parts.length !== 2 ||
        parts[0].toLowerCase() !==
            "bearer"
    ) {
        return null;
    }

    const token =
        parts[1]?.trim();

    if (!token) {
        return null;
    }

    return token;
};

/*
|--------------------------------------------------------------------------
| Build User Auth Context
|--------------------------------------------------------------------------
*/

const buildUserAuthContext = (
    payload: AccessTokenPayload
): UserAuthContext => {
    const {
        sub,
        tokenType,
        iat,
        exp,
        ...additionalClaims
    } = payload;

    return Object.freeze({
        userId: sub,

        ...(typeof iat === "number"
            ? {
                  tokenIssuedAt: iat,
              }
            : {}),

        ...(typeof exp === "number"
            ? {
                  tokenExpiresAt: exp,
              }
            : {}),

        claims: Object.freeze({
            ...additionalClaims,
        }),
    });
};

/*
|--------------------------------------------------------------------------
| User Authentication
|--------------------------------------------------------------------------
*/

export const userAuth: RequestHandler = (
    req: Request,
    res: Response,
    next: NextFunction
) => {
    const token =
        extractBearerToken(
            req.headers.authorization
        );

    if (!token) {
        res.status(401).json({
            success: false,
            message:
                "User authentication required.",
        });

        return;
    }

    try {
        const payload =
            verifyAccessToken(token);

        /*
        |--------------------------------------------------------------------------
        | Token Type Validation
        |--------------------------------------------------------------------------
        */

        if (
            payload.tokenType !==
            "access"
        ) {
            res.status(401).json({
                success: false,
                message:
                    "Invalid user authentication token.",
            });

            return;
        }

        /*
        |--------------------------------------------------------------------------
        | Build User Context
        |--------------------------------------------------------------------------
        */

        req.userAuth =
            buildUserAuthContext(
                payload
            );

        next();
    } catch {
        res.status(401).json({
            success: false,
            message:
                "Invalid or expired user authentication token.",
        });

        return;
    }
};

/*
|--------------------------------------------------------------------------
| Require User
|--------------------------------------------------------------------------
*/

export const requireUser: RequestHandler = (
    req,
    res,
    next
) => {
    if (!req.userAuth?.userId) {
        res.status(401).json({
            success: false,
            message:
                "User authentication required.",
        });

        return;
    }

    next();
};

/*
|--------------------------------------------------------------------------
| Get Authenticated User ID
|--------------------------------------------------------------------------
*/

export const getAuthenticatedUserId = (
    req: Request
): string => {
    const userId =
        req.userAuth?.userId;

    if (!userId) {
        throw new Error(
            "Authenticated user context is missing."
        );
    }

    return userId;
};

/*
|--------------------------------------------------------------------------
| Check User Authentication
|--------------------------------------------------------------------------
*/

export const isUserAuthenticated = (
    req: Request
): boolean => {
    return Boolean(
        req.userAuth?.userId
    );
};

