/*
|--------------------------------------------------------------------------
| Constants
|--------------------------------------------------------------------------
*/

const ADMIN_REFRESH_COOKIE =
    "noptrix_admin_rt";

const ADMIN_REFRESH_COOKIE_PATH =
    "/api/admin-auth";


/*
|--------------------------------------------------------------------------
| Cookie Helpers
|--------------------------------------------------------------------------
*/

const getAdminRefreshCookieOptions = () => ({
    httpOnly: true,

    secure:
        process.env.NODE_ENV === "production",

    sameSite:
        "strict" as const,

    path:
        ADMIN_REFRESH_COOKIE_PATH,
});


const setAdminRefreshCookie = (
    res: Response,
    refreshToken: string,
): void => {

    res.cookie(
        ADMIN_REFRESH_COOKIE,
        refreshToken,
        {
            ...getAdminRefreshCookieOptions(),

            maxAge:
                7 *
                24 *
                60 *
                60 *
                1000,
        },
    );
};


const clearAdminRefreshCookie = (
    res: Response,
): void => {

    res.clearCookie(
        ADMIN_REFRESH_COOKIE,
        getAdminRefreshCookieOptions(),
    );
};


/*
|--------------------------------------------------------------------------
| Helpers
|--------------------------------------------------------------------------
*/

const getSessionIdFromRequest = (
    req: Request,
): string => {

    const sessionId =
        req.adminAuth?.claims?.sessionId;

    if (
        typeof sessionId !== "string" ||
        !sessionId.trim()
    ) {
        throw ApiError.unauthorized(
            "Admin session information is missing.",
            {
                code:
                    "ADMIN_SESSION_ID_MISSING",
            },
        );
    }

    return sessionId.trim();
};

const sendAdminLoginSuccess = (
    res: Response,
    result: AdminAuthenticationResult,
): void => {
    const refreshToken = result.tokens.refreshToken;

    if (typeof refreshToken !== "string" || !refreshToken.trim()) {
        throw ApiError.internal(
            "Admin refresh token was not generated.",
            { code: "ADMIN_REFRESH_TOKEN_MISSING" },
        );
    }

    setAdminRefreshCookie(res, refreshToken);

    res.status(200).json({
        success: true,
        message: "Admin login successful.",
        data: {
            ...result,
            tokens: {
                accessToken: result.tokens.accessToken,
            },
        },
    });
};


/*
|--------------------------------------------------------------------------
| Login
|--------------------------------------------------------------------------
*/

export const loginAdminController =
    asyncHandler(
        async (
            req: Request,
            res: Response,
        ) => {

            const result =
                await loginAdmin(
                    {
                        email:
                            req.body.email,

                        password:
                            req.body.password,
                    },
                    {
                        userAgent:
                            req.get(
                                "user-agent",
                            ),

                        ipAddress:
                            req.ip,

                        deviceId:
                            typeof req.body.deviceId ===
                            "string"
                                ? req.body.deviceId
                                : undefined,
                    },
                );

            if ("verificationRequired" in result) {
                res.status(200).json({
                    success: true,
                    message: "A login verification code was sent to your email.",
                    data: result,
                });
                return;
            }

            sendAdminLoginSuccess(res, result);
        },
    );

export const verifyAdminLoginController = asyncHandler(
    async (req: Request, res: Response) => {
        const input = adminLoginVerificationSchema.parse(req.body);
        const result = await verifyAdminLogin(input.challengeId, input.code, {
            userAgent: req.get("user-agent"),
            ipAddress: req.ip,
            deviceId:
                typeof req.body.deviceId === "string"
                    ? req.body.deviceId
                    : undefined,
        });

        sendAdminLoginSuccess(res, result);
    },
);

export const resendAdminLoginCodeController = asyncHandler(
    async (req: Request, res: Response) => {
        const { challengeId } =
            resendAdminLoginVerificationSchema.parse(req.body);
        const result = await resendAdminLoginCode(challengeId);

        res.status(200).json({
            success: true,
            message: "A new login verification code was sent.",
            data: result,
        });
    },
);


