/*
|--------------------------------------------------------------------------
| Refresh Access Token
|--------------------------------------------------------------------------
*/

export const refreshAdminTokenController =
    asyncHandler(
        async (
            req: Request,
            res: Response,
        ) => {

            const refreshToken =
                req.cookies?.[
                    ADMIN_REFRESH_COOKIE
                ];

            if (
                typeof refreshToken !==
                "string" ||
                !refreshToken.trim()
            ) {
                throw ApiError.unauthorized(
                    "Admin refresh session is missing.",
                    {
                        code:
                            "ADMIN_REFRESH_COOKIE_MISSING",
                    },
                );
            }

            const result =
                await refreshAdminAccessToken(
                    refreshToken,
                );

            /*
             * Rotate refresh cookie.
             */

            setAdminRefreshCookie(
                res,
                result.refreshToken,
            );

            /*
             * Never expose refresh token
             * to the frontend JavaScript.
             */

            const {
                refreshToken: _refreshToken,
                ...safeResult
            } = result;

            res.status(200).json({
                success: true,

                message:
                    "Admin access token refreshed successfully.",

                data:
                    safeResult,
            });
        },
    );


/*
|--------------------------------------------------------------------------
| Logout
|--------------------------------------------------------------------------
*/

export const logoutAdminController =
    asyncHandler(
        async (
            req: Request,
            res: Response,
        ) => {

            const adminId =
                getAuthenticatedAdminId(
                    req,
                );

            const sessionId =
                getSessionIdFromRequest(
                    req,
                );

            await logoutAdmin(
                adminId,
                sessionId,
            );

            clearAdminRefreshCookie(
                res,
            );

            res.status(200).json({
                success: true,

                message:
                    "Admin logout successful.",
            });
        },
    );


/*
|--------------------------------------------------------------------------
| Verify Admin Secret
|--------------------------------------------------------------------------
*/

export const verifyAdminSecretController =
    asyncHandler(
        async (
            req: Request,
            res: Response,
        ) => {

            const adminId =
                getAuthenticatedAdminId(
