const normalizeSearch = (
    value?: string
): string | undefined => {
    if (
        value === undefined
    ) {
        return undefined;
    }

    const normalized =
        value.trim();

    if (
        normalized.length === 0
    ) {
        return undefined;
    }

    return normalized.slice(
        0,
        MAX_SEARCH_LENGTH
    );
};

const generateCategorySlug = (
    name: string
): string => {
    const slug =
        slugify(
            name,
            {
                lower: true,
                strict: true,
                trim: true,
            }
        );

    if (!slug) {
        throw ApiError.badRequest(
            "Unable to generate a valid category slug from the provided name.",
            {
                code:
                    "INVALID_CATEGORY_SLUG",
            }
        );
    }

    return slug;
};

const normalizeSlug = (
    slug: string
): string => {
    const normalized =
        slugify(
            slug,
            {
                lower: true,
                strict: true,
                trim: true,
