        );

    if (!normalized) {
        throw ApiError.badRequest(
            "A valid category slug is required.",
            {
                code:
                    "INVALID_CATEGORY_SLUG",
            }
        );
    }

    return normalized;
};

const ensureObjectId = (
    value: string,
    fieldName: string
): Types.ObjectId => {
    if (
        !Types.ObjectId.isValid(
            value
        )
    ) {
        throw ApiError.badRequest(
            `Invalid ${fieldName}.`,
            {
                code:
                    "INVALID_OBJECT_ID",
            }
        );
    }

    return new Types.ObjectId(
        value
    );
};

const mapCloudinaryImage = (
    result: CloudinaryUploadResult
): CategoryImage => {
    if (
        result.resourceType !== "image"
    ) {
        throw ApiError.internal(
            "Cloudinary returned an invalid resource type for a category image.",
            {
                code:
                    "INVALID_CATEGORY_IMAGE_RESOURCE_TYPE",
                details: {
                    resourceType:
                        result.resourceType,
                },
            }
        );
    }

    return {
        publicId:
            result.publicId,
        secureUrl:
            result.secureUrl,
        url:
            result.url,
        assetId:
            result.assetId,
        version:
            result.version,
        resourceType:
            result.resourceType,
        format:
            result.format,
        bytes:
            result.bytes,
        width:
            result.width,
        height:
            result.height,
        originalFilename:
            result.originalFilename,
    };
};

