import { Types } from "mongoose";

import {
    Integration,
    type IIntegration,
} from "./integration.model";

import type {
    CreateIntegrationInput,
    ListIntegrationsQuery,
    UpdateIntegrationInput,
} from "./integration.validator";

export class IntegrationServiceError extends Error {
    constructor(
        message: string,
        public readonly statusCode: number,
        public readonly code: string,
    ) {
        super(message);
        this.name = "IntegrationServiceError";
    }
}

function toSafeIntegration(
    record: Record<string, unknown>,
) {
    const {
        secretEnvKeys,
        lastError,
        ...safe
    } = record;

    return {
        ...safe,
        secretsConfigured:
            Array.isArray(secretEnvKeys) &&
            secretEnvKeys.length > 0,
        hasRecentError: Boolean(lastError),
    };
}

export async function createIntegration(
    input: CreateIntegrationInput,
    actorId?: string,
) {
    const existing = await Integration.exists({
        name: input.name,
    });

    if (existing) {
        throw new IntegrationServiceError(
            "An integration with this name already exists.",
            409,
            "INTEGRATION_ALREADY_EXISTS",
        );
    }

    const record = await Integration.create({
        ...input,
        status: "INACTIVE",
        createdBy: actorId,
        updatedBy: actorId,
    });

    return toSafeIntegration(
        record.toObject() as unknown as Record<string, unknown>,
    );
}

export async function listIntegrations(
    query: ListIntegrationsQuery,
) {
    const filter: Record<string, unknown> = {};

    if (query.status) filter.status = query.status;
    if (query.provider) {
        filter.provider = query.provider.toLowerCase();
    }

    if (query.search) {
        const escaped = query.search.replace(
            /[.*+?^${}()|[\]\\]/g,
            "\\$&",
        );

        filter.$or = [
            { name: { $regex: escaped, $options: "i" } },
            { provider: { $regex: escaped, $options: "i" } },
        ];
    }

    const skip = (query.page - 1) * query.limit;

    const [records, total] = await Promise.all([
        Integration.find(filter)
            .select("-secretEnvKeys -lastError")
            .sort({ updatedAt: -1, _id: -1 })
            .skip(skip)
            .limit(query.limit)
            .lean()
            .exec(),
        Integration.countDocuments(filter).exec(),
    ]);

    return {
        items: records.map((record) =>
            toSafeIntegration(
                record as unknown as Record<string, unknown>,
            ),
        ),
        pagination: {
            page: query.page,
            limit: query.limit,
            total,
            totalPages: Math.ceil(total / query.limit),
            hasNextPage: skip + records.length < total,
            hasPreviousPage: query.page > 1,
        },
    };
}

export async function getIntegrationById(id: string) {
    if (!Types.ObjectId.isValid(id)) {
        throw new IntegrationServiceError(
            "Invalid integration ID.",
            400,
            "INVALID_INTEGRATION_ID",
        );
    }

    const record = await Integration.findById(id)
        .select("-secretEnvKeys -lastError")
        .lean()
        .exec();

    if (!record) {
        throw new IntegrationServiceError(
            "Integration not found.",
            404,
            "INTEGRATION_NOT_FOUND",
        );
    }

    return toSafeIntegration(
        record as unknown as Record<string, unknown>,
    );
}

export async function updateIntegration(
    id: string,
    input: UpdateIntegrationInput,
    actorId?: string,
) {
    if (!Types.ObjectId.isValid(id)) {
        throw new IntegrationServiceError(
            "Invalid integration ID.",
            400,
            "INVALID_INTEGRATION_ID",
        );
    }

    const record = await Integration.findByIdAndUpdate(
        id,
        {
            $set: {
                ...input,
                updatedBy: actorId,
            },
        },
        {
            new: true,
            runValidators: true,
        },
    )
        .select("-secretEnvKeys -lastError")
        .lean()
        .exec();

    if (!record) {
        throw new IntegrationServiceError(
            "Integration not found.",
            404,
            "INTEGRATION_NOT_FOUND",
        );
    }

    return toSafeIntegration(
        record as unknown as Record<string, unknown>,
    );
}

export async function deleteIntegration(id: string) {
    if (!Types.ObjectId.isValid(id)) {
        throw new IntegrationServiceError(
            "Invalid integration ID.",
            400,
            "INVALID_INTEGRATION_ID",
        );
    }

    const record = await Integration.findByIdAndDelete(id).exec();

    if (!record) {
        throw new IntegrationServiceError(
            "Integration not found.",
            404,
            "INTEGRATION_NOT_FOUND",
        );
    }
}

export async function markIntegrationChecked(
    id: string,
    successful: boolean,
    errorMessage?: string,
) {
    const update: Record<string, unknown> = {
        lastCheckedAt: new Date(),
        status: successful ? "ACTIVE" : "ERROR",
    };

    if (successful) {
        update.lastError = undefined;
    } else {
        update.lastError = (errorMessage || "Integration check failed.")
            .slice(0, 2000);
    }

    await Integration.findByIdAndUpdate(
        id,
        { $set: update },
        { runValidators: true },
    ).exec();
}

import {
    NextFunction,
    Request,
    Response,
} from "express";

import {
    hasPermissionMatch,
} from "../../middlewares/permission.middleware";

import {
    ApiError,
} from "../../utils/ApiError";

/*
|--------------------------------------------------------------------------
| Job Application Status Permission
|--------------------------------------------------------------------------
|
| SELECTED
|   -> job_applications.approve
|
| REJECTED
|   -> job_applications.reject
|
| Other statuses
|   -> job_applications.update
|
| job_applications.manage
|   -> Full access
|
| OWNER
|   -> Automatically allowed by permission middleware
|
|--------------------------------------------------------------------------
*/

export const requireJobApplicationStatusPermission = (
    req: Request,
    _res: Response,
    next: NextFunction,
): void => {
    const status =
        typeof req.body?.status === "string"
            ? req.body.status
                .trim()
                .toUpperCase()
            : "";

    let allowed = false;

    /*
    |--------------------------------------------------------------------------
    | SELECTED
    |--------------------------------------------------------------------------
    */

    if (status === "SELECTED") {
        allowed =
            hasPermissionMatch(
                req,
                "job_applications.approve",
            ) ||
            hasPermissionMatch(
                req,
                "job_applications.manage",
            );
    }

    /*
    |--------------------------------------------------------------------------
    | REJECTED
    |--------------------------------------------------------------------------
    */

    else if (status === "REJECTED") {
        allowed =
            hasPermissionMatch(
                req,
                "job_applications.reject",
            ) ||
            hasPermissionMatch(
                req,
                "job_applications.manage",
            );
    }

    /*
    |--------------------------------------------------------------------------
    | Other Status Updates
    |--------------------------------------------------------------------------
    */

    else {
        allowed =
            hasPermissionMatch(
                req,
                "job_applications.update",
            ) ||
            hasPermissionMatch(
                req,
                "job_applications.manage",
            );
    }

    /*
    |--------------------------------------------------------------------------
    | Authorization Failure
    |--------------------------------------------------------------------------
    */

    if (!allowed) {
        throw ApiError.forbidden(
            "You do not have permission to perform this job application status action.",
        );
    }

    next();
};

import {
    Types,
} from "mongoose";

import bcrypt from "bcryptjs";

import {
    Owner,
} from "../owners/owner.model";

import {
    User,
} from "../users/user.model";

import {
    verifyUserPassword,
} from "../users/user.service";

import {
    generateAccessToken,
    generateRefreshToken,
    tryVerifyRefreshToken,
} from "../../utils/token";

import {
    ApiError,
} from "../../utils/ApiError";

import {
    createSession,
    findSessionByRefreshToken,
    revokeUserSession,
    touchSession,
} from "../sessions/session.service";

import {
    Session,
} from "../sessions/session.model";

import {
    OwnerLoginInput,
    OwnerTokenPair,
    OwnerAuthenticationResult,
    OwnerSecretVerificationResult,
} from "./owner-auth.types";


/*
|--------------------------------------------------------------------------
| Helpers
|--------------------------------------------------------------------------
*/

const ensureValidObjectId = (
    value: string,
    fieldName: string
): Types.ObjectId => {
    if (!Types.ObjectId.isValid(value)) {
        throw ApiError.badRequest(
            `Invalid ${fieldName}.`,
            {
                code:
                    "INVALID_OBJECT_ID",
            }
        );
    }

    return new Types.ObjectId(value);
};


/*
|--------------------------------------------------------------------------
| Generate Owner Token Pair
|--------------------------------------------------------------------------
|
| IMPORTANT:
|
| The User ID is the canonical identity.
|
| OWNER authorization data is explicitly
| attached to the access token because
| ownerAuth.middleware.ts currently requires
| the OWNER role boundary.
|
| secretVerified is always false for
| a newly generated authentication pair.
|
|--------------------------------------------------------------------------
*/

const generateOwnerTokenPair = (
    userId: string,
    sessionId: string
): OwnerTokenPair => {
    return {
        accessToken:
            generateAccessToken(
                userId,
                {
                    role:
                        "OWNER",

                    sessionId,

                    secretVerified:
                        false,
                }
            ),

        refreshToken:
            generateRefreshToken(
                userId
            ),

        secretVerified:
            false,
    };
};


/*
|--------------------------------------------------------------------------
| Login Owner
|--------------------------------------------------------------------------
*/

export const loginOwner = async (
    input: OwnerLoginInput,
    metadata?: {
        readonly userAgent?: string;
        readonly ipAddress?: string;
        readonly deviceId?: string;
    }
): Promise<OwnerAuthenticationResult> => {

    const email =
        input.email
            .trim()
            .toLowerCase();

    /*
     * User is the canonical identity.
     */

    const user =
        await User.findOne({
            email,
        }).select(
            "+password"
        );

    if (!user) {
        throw ApiError.unauthorized(
            "Invalid email or password.",
            {
                code:
                    "INVALID_OWNER_CREDENTIALS",
            }
        );
    }

    /*
     * User account status.
     */

    if (
        user.status ===
        "SUSPENDED"
    ) {
        throw ApiError.forbidden(
            "Owner account is suspended.",
            {
                code:
                    "OWNER_ACCOUNT_SUSPENDED",
            }
        );
    }

    if (
        user.status ===
        "BLOCKED"
    ) {
        throw ApiError.forbidden(
            "Owner account is blocked.",
            {
                code:
                    "OWNER_ACCOUNT_BLOCKED",
            }
        );
    }

    if (
        user.status ===
        "INACTIVE"
    ) {
        throw ApiError.forbidden(
            "Owner account is inactive.",
            {
                code:
                    "OWNER_ACCOUNT_INACTIVE",
            }
        );
    }

    if (
        user.status !==
        "ACTIVE"
    ) {
        throw ApiError.forbidden(
            "Owner account is not active.",
            {
                code:
                    "OWNER_ACCOUNT_NOT_ACTIVE",
            }
        );
    }

    /*
     * Verify password.
     */

    const passwordValid =
        await verifyUserPassword(
            user,
            input.password
        );

    if (!passwordValid) {
        throw ApiError.unauthorized(
            "Invalid email or password.",
            {
                code:
                    "INVALID_OWNER_CREDENTIALS",
            }
        );
    }

    /*
     * Owner profile must already exist.
     *
     * OWNER creation belongs exclusively
     * to the seed/bootstrap process.
     */

    const owner =
        await Owner.findOne({
            userId:
                user._id,
        });

    if (!owner) {
        throw ApiError.forbidden(
            "Owner profile is not configured.",
            {
                code:
                    "OWNER_PROFILE_NOT_CONFIGURED",
            }
        );
    }

    /*
     * Immutable OWNER role verification.
     */

    if (
        owner.role !==
        "OWNER"
    ) {
        throw ApiError.forbidden(
            "Invalid owner profile.",
            {
                code:
                    "INVALID_OWNER_ROLE",
            }
        );
    }

    /*
     * Owner profile status.
     */

    if (
        owner.status ===
        "SUSPENDED"
    ) {
        throw ApiError.forbidden(
            "Owner profile is suspended.",
            {
                code:
                    "OWNER_PROFILE_SUSPENDED",
            }
        );
    }

    if (
        owner.status ===
        "INACTIVE"
    ) {
        throw ApiError.forbidden(
            "Owner profile is inactive.",
            {
                code:
                    "OWNER_PROFILE_INACTIVE",
            }
        );
    }

    if (
        owner.status !==
        "ACTIVE"
    ) {
        throw ApiError.forbidden(
            "Owner profile is not active.",
            {
                code:
                    "OWNER_PROFILE_NOT_ACTIVE",
            }
        );
    }

    /*
     * Generate refresh token first.
     */

    const refreshToken =
        generateRefreshToken(
            user._id.toString()
        );

    const refreshPayload =
        tryVerifyRefreshToken(
            refreshToken
        );

    if (!refreshPayload) {
        throw ApiError.internal(
            "Failed to create owner refresh token.",
            {
                code:
                    "OWNER_REFRESH_TOKEN_GENERATION_FAILED",
            }
        );
    }

    if (
        typeof refreshPayload.exp !==
        "number"
    ) {
        throw ApiError.internal(
            "Owner refresh token expiry is missing.",
            {
                code:
                    "OWNER_REFRESH_TOKEN_EXPIRY_MISSING",
            }
        );
    }

    /*
     * Persistent authentication session.
     */

    const session =
        await createSession({
            userId:
                user._id.toString(),

            refreshToken,

            userAgent:
                metadata?.userAgent,

            ipAddress:
                metadata?.ipAddress,

            deviceId:
                metadata?.deviceId,

            expiresAt:
                new Date(
                    refreshPayload.exp *
                        1000
                ),
        });

    /*
     * Generate access token using
     * the actual session ID.
     */

    const accessToken =
        generateAccessToken(
            user._id.toString(),
            {
                role:
                    "OWNER",

                sessionId:
                    session._id.toString(),

                secretVerified:
                    false,
            }
        );

    /*
     * Update login information.
     */

    user.lastLoginAt =
        new Date();

    user.failedLoginAttempts =
        0;

    user.lockedUntil =
        undefined;

    await user.save();

    owner.lastLoginAt =
        new Date();

    await owner.save();

    return {
        userId:
            user._id.toString(),

        ownerId:
            owner._id.toString(),

        tokens: {
            accessToken,
            refreshToken,

            secretVerified:
                false,
        },

        sessionId:
            session._id.toString(),

        secretVerified:
            false,
    };
};


/*
|--------------------------------------------------------------------------
| Verify Owner Secret Code
|--------------------------------------------------------------------------
*/

export const verifyOwnerSecretCode = async (
    userId: string,
    sessionId: string,
    secretCode: string
): Promise<OwnerSecretVerificationResult> => {

    const _userId =
        ensureValidObjectId(
            userId,
            "user ID"
        );

    const _sessionId =
        ensureValidObjectId(
            sessionId,
            "session ID"
        );

    /*
     * Resolve Owner profile.
     */

    const owner =
        await Owner.findOne({
            userId:
                _userId,
        }).select(
            "+secretCodeHash"
        );

    if (!owner) {
        throw ApiError.forbidden(
            "Owner profile is not configured.",
            {
                code:
                    "OWNER_PROFILE_NOT_CONFIGURED",
            }
        );
    }

    if (
        owner.role !==
        "OWNER"
    ) {
        throw ApiError.forbidden(
            "Invalid owner profile.",
            {
                code:
                    "INVALID_OWNER_ROLE",
            }
        );
    }

    if (
        owner.status !==
        "ACTIVE"
    ) {
        throw ApiError.forbidden(
            "Owner profile is not active.",
            {
                code:
                    "OWNER_PROFILE_NOT_ACTIVE",
            }
        );
    }

    /*
     * Verify the session belongs
     * to this canonical User identity.
     */

    const session =
        await Session.findOne({
            _id:
                _sessionId,

            userId:
                _userId,

            status:
                "ACTIVE",

            expiresAt: {
                $gt:
                    new Date(),
            },
        }).exec();

    if (!session) {
        throw ApiError.unauthorized(
            "Session is invalid, expired, or revoked.",
            {
                code:
                    "INVALID_OWNER_SESSION",
            }
        );
    }

    /*
     * Secret validation.
     */

    const normalizedSecret =
        secretCode.trim();

    if (!normalizedSecret) {
        throw ApiError.badRequest(
            "Owner secret code is required.",
            {
                code:
                    "OWNER_SECRET_REQUIRED",
            }
        );
    }

    const secretValid =
        await bcrypt.compare(
            normalizedSecret,
            owner.secretCodeHash
        );

    if (!secretValid) {
        throw ApiError.unauthorized(
            "Invalid owner secret code.",
            {
                code:
                    "INVALID_OWNER_SECRET",
            }
        );
    }

    /*
     * Persist secret verification
     * on the authenticated session.
     */

    session.secretVerified =
        true;

    await session.save();

    /*
     * Issue verified access token.
     */

    const accessToken =
        generateAccessToken(
            _userId.toString(),
            {
                role:
                    "OWNER",

                sessionId:
                    _sessionId.toString(),

                secretVerified:
                    true,
            }
        );

    const verifiedAt =
        new Date();

    owner.secretVerifiedAt =
        verifiedAt;

    owner.lastSecretVerificationAt =
        verifiedAt;

    await owner.save();

    await touchSession(
        _sessionId.toString()
    );

    return {
        userId:
            _userId.toString(),

        ownerId:
            owner._id.toString(),

        accessToken,

        sessionId:
            _sessionId.toString(),

        secretVerified:
            true,
    };
};


/*
|--------------------------------------------------------------------------
| Refresh Owner Access Token
|--------------------------------------------------------------------------
|
| IMPORTANT:
|
| Refresh rotation preserves the OWNER security
| state stored on the authenticated session.
|
| If the current session has:
|
| secretVerified=true
|
| then the rotated session and new access token
| retain:
|
| secretVerified=true
|
| This prevents a normal refresh from forcing the
| OWNER to repeat secret verification unnecessarily.
|
|--------------------------------------------------------------------------
*/

export const refreshOwnerAccessToken =
    async (
        refreshToken: string
    ): Promise<OwnerTokenPair> => {

        const payload =
            tryVerifyRefreshToken(
                refreshToken
            );

        if (!payload) {
            throw ApiError.unauthorized(
                "Invalid or expired owner refresh token.",
                {
                    code:
                        "INVALID_OWNER_REFRESH_TOKEN",
                }
            );
        }

        const userId =
            payload.sub;

        if (!userId) {
            throw ApiError.unauthorized(
                "Invalid owner refresh token.",
                {
                    code:
                        "INVALID_OWNER_REFRESH_TOKEN",
                }
            );
        }

        ensureValidObjectId(
            userId,
            "user ID"
        );

        /*
         * Locate persistent session.
         */

        const session =
            await findSessionByRefreshToken(
                refreshToken
            );

        if (!session) {
            throw ApiError.unauthorized(
                "Owner session is invalid, expired, or revoked.",
                {
                    code:
                        "INVALID_OWNER_SESSION",
                }
            );
        }

        /*
         * Ensure token and session
         * belong to the same User.
         */

        if (
            session.userId.toString() !==
            userId
        ) {
            throw ApiError.unauthorized(
                "Invalid owner refresh token.",
                {
                    code:
                        "OWNER_REFRESH_TOKEN_MISMATCH",
                }
            );
        }

        /*
         * Owner profile must still exist
         * and remain active.
         */

        const owner =
            await Owner.findOne({
                userId,
            });

        if (!owner) {
            throw ApiError.unauthorized(
                "Owner profile was not found.",
                {
                    code:
                        "OWNER_PROFILE_NOT_CONFIGURED",
                }
            );
        }

        if (
            owner.role !==
            "OWNER"
        ) {
            throw ApiError.unauthorized(
                "Invalid owner profile.",
                {
                    code:
                        "INVALID_OWNER_ROLE",
                }
            );
        }

        if (
            owner.status !==
            "ACTIVE"
        ) {
            throw ApiError.forbidden(
                "Owner profile is not active.",
                {
                    code:
                        "OWNER_PROFILE_NOT_ACTIVE",
                }
            );
        }

        /*
         * User account must still be active.
         */

        const user =
            await User.findById(
                userId
            );

        if (!user) {
            throw ApiError.unauthorized(
                "Owner user account was not found.",
                {
                    code:
                        "OWNER_USER_NOT_FOUND",
                }
            );
        }

        if (
            user.status !==
            "ACTIVE"
        ) {
            throw ApiError.forbidden(
                "Owner account is not active.",
                {
                    code:
                        "OWNER_ACCOUNT_NOT_ACTIVE",
                }
            );
        }

        /*
         * Generate new refresh token.
         */

        const newRefreshToken =
            generateRefreshToken(
                userId
            );

        const newRefreshPayload =
            tryVerifyRefreshToken(
                newRefreshToken
            );

        if (!newRefreshPayload) {
            throw ApiError.internal(
                "Failed to create owner refresh token.",
                {
                    code:
                        "OWNER_REFRESH_TOKEN_GENERATION_FAILED",
                }
            );
        }

        if (
            typeof newRefreshPayload.exp !==
            "number"
        ) {
            throw ApiError.internal(
                "Owner refresh token expiry is missing.",
                {
                    code:
                        "OWNER_REFRESH_TOKEN_EXPIRY_MISSING",
                }
            );
        }

        /*
         * Revoke old session.
         */

        const revoked =
            await revokeUserSession(
                userId,
                session._id.toString()
            );

        if (!revoked) {
            throw ApiError.unauthorized(
                "Owner session is no longer active.",
                {
                    code:
                        "OWNER_SESSION_REVOKED",
                }
            );
        }

        /*
         * Create rotated session.
         */

        const newSession =
            await createSession({
                userId,

                refreshToken:
                    newRefreshToken,

                secretVerified:
                    session.secretVerified,

                userAgent:
                    session.userAgent,

                ipAddress:
                    session.ipAddress,

                deviceId:
                    session.deviceId,

                expiresAt:
                    new Date(
                        newRefreshPayload.exp *
                            1000
                    ),
            });

        await touchSession(
            newSession._id.toString()
        );

        /*
         * IMPORTANT:
         *
         * Secret verification is NOT carried
         * over during refresh.
         */

        const accessToken =
            generateAccessToken(
                userId,
                {
                    role:
                        "OWNER",

                    sessionId:
                        newSession._id.toString(),

                    secretVerified:
                        session.secretVerified,
                }
            );

        return {
            accessToken,

            refreshToken:
                newRefreshToken,

            secretVerified:
                session.secretVerified,
        };
    };


/*
|--------------------------------------------------------------------------
| Logout Owner
|--------------------------------------------------------------------------
*/

export const logoutOwner = async (
    userId: string,
    sessionId: string
): Promise<void> => {

    ensureValidObjectId(
        userId,
        "user ID"
    );

    ensureValidObjectId(
        sessionId,
        "session ID"
    );

    const session =
        await revokeUserSession(
            userId,
            sessionId
        );

    if (!session) {
        throw ApiError.notFound(
            "Owner session not found or already revoked.",
            {
                code:
                    "OWNER_SESSION_NOT_FOUND",
            }
        );
    }
};

import { z } from "zod";

import {
    Types,
} from "mongoose";


/*
|--------------------------------------------------------------------------
| OWNER AUTH VALIDATION
|--------------------------------------------------------------------------
|
| Advanced validation layer for the OWNER authentication boundary.
|
| Goals:
|
| 1. Strong password policy (complexity, not just length).
| 2. Strict, format-aware secret-code validation.
| 3. ObjectId-aware sessionId validation (fails fast before
|    hitting the database instead of throwing a generic
|    Mongoose CastError downstream).
| 4. Defense against whitespace / null-byte / control-character
|    injection in security-sensitive fields.
| 5. Reusable primitives so future OWNER-scoped schemas stay
|    consistent instead of re-implementing the same rules.
|
|--------------------------------------------------------------------------
*/


/*
|--------------------------------------------------------------------------
| Shared Primitives
|--------------------------------------------------------------------------
*/

/**
 * Rejects control characters (including null bytes) that have
 * no business being in user-submitted auth fields but can slip
 * through naive `.trim()` validation.
 */
const NO_CONTROL_CHARS_REGEX =
    /^[^\x00-\x1F\x7F]*$/;

const noControlChars = (
    message: string
) =>
    z
        .string()
        .regex(
            NO_CONTROL_CHARS_REGEX,
            message
        );

/**
 * Mongo ObjectId format check.
 *
 * Prevents malformed IDs from reaching the database layer,
 * where they would otherwise surface as an opaque
 * `CastError` instead of a clean 400 response.
 */
const objectIdSchema = (
    fieldName: string
) =>
    z
        .string()
        .trim()
        .refine(
            (value) =>
                Types.ObjectId.isValid(
                    value
                ),
            {
                message: `Invalid ${fieldName}.`,
            }
        );

/**
 * Password complexity policy.
 *
 * Requires at least one:
 * - lowercase letter
 * - uppercase letter
 * - digit
 * - special character
 *
 * This is intentionally stricter for OWNER accounts than a
 * typical end-user account, since OWNER is the highest
 * privileged boundary in the system.
 */
const passwordComplexitySchema = z
    .string()
    .min(
        8,
        "Password must be at least 8 characters."
    )
    .max(
        128,
        "Password cannot exceed 128 characters."
    )
    .refine(
        (value) => /[a-z]/.test(value),
        "Password must contain at least one lowercase letter."
    )
    .refine(
        (value) => /[A-Z]/.test(value),
        "Password must contain at least one uppercase letter."
    )
    .refine(
        (value) => /[0-9]/.test(value),
        "Password must contain at least one digit."
    )
    .refine(
        (value) =>
            /[^A-Za-z0-9]/.test(value),
        "Password must contain at least one special character."
    )
    .refine(
        (value) => !/\s/.test(value),
        "Password cannot contain whitespace."
    );

/**
 * Secret-code policy.
 *
 * The secret code is the OWNER's second authentication factor,
 * so it is validated more strictly than a generic string:
 *
 * - fixed, bounded length range
 * - digits only by default (adjust the regex if your secret
 *   codes are alphanumeric)
 * - no leading/trailing whitespace tolerated after trim
 */
const secretCodeSchema = noControlChars(
    "Secret code contains invalid characters."
)
    .trim()
    .min(
        4,
        "Secret code must be at least 4 characters."
    )
    .max(
        32,
        "Secret code cannot exceed 32 characters."
    )
    .regex(
        /^[A-Za-z0-9]+$/,
        "Secret code may only contain letters and numbers."
    );


/*
|--------------------------------------------------------------------------
| OWNER Login Validation
|--------------------------------------------------------------------------
*/

export const ownerLoginSchema = z
    .object({
        email: noControlChars(
            "Email contains invalid characters."
        )
            .trim()
            .toLowerCase()
            .pipe(
                z
                    .string()
                    .email(
                        "A valid email address is required."
                    )
                    .max(
                        254,
                        "Email address is too long."
                    )
            ),

        password: passwordComplexitySchema,
    })
    .strict();


/*
|--------------------------------------------------------------------------
| OWNER Secret Verification Validation
|--------------------------------------------------------------------------
*/

export const ownerSecretVerificationSchema =
    z
        .object({
            secretCode: secretCodeSchema,
            sessionId: objectIdSchema(
                "session ID"
            ).optional(),
        })
        .strict();


/*
|--------------------------------------------------------------------------
| OWNER Logout Validation
|--------------------------------------------------------------------------
*/

export const ownerLogoutSchema = z
    .object({
        sessionId: objectIdSchema(
            "session ID"
        ),
    })
    .strict();


/*
|--------------------------------------------------------------------------
| OWNER Session-Scoped Secret Verification
|--------------------------------------------------------------------------
|
| Combines sessionId + secretCode in a single schema for routes
| that verify the secret code against an explicit session
| (rather than pulling sessionId from an auth-context middleware).
|
|--------------------------------------------------------------------------
*/

export const ownerSecretVerificationWithSessionSchema =
    z
        .object({
            sessionId: objectIdSchema(
                "session ID"
            ),

            secretCode: secretCodeSchema,
        })
        .strict();


/*
|--------------------------------------------------------------------------
| Safe Parse Helpers
|--------------------------------------------------------------------------
|
| Thin wrappers that flatten Zod's error tree into a single,
| ordered list of human-readable messages — convenient for
| API error payloads without leaking Zod's internal shape.
|
|--------------------------------------------------------------------------
*/

export const formatValidationErrors = (
    error: z.ZodError
): readonly string[] => {
    return error.issues.map(
        (issue) => issue.message
    );
};

export const safeValidate = <
    Schema extends z.ZodTypeAny
>(
    schema: Schema,
    data: unknown
):
    | {
          readonly success: true;
          readonly data: z.infer<Schema>;
      }
    | {
          readonly success: false;
          readonly errors: readonly string[];
      } => {
    const result =
        schema.safeParse(data);

    if (!result.success) {
        return {
            success: false,
            errors:
                formatValidationErrors(
                    result.error
                ),
        };
    }

    return {
        success: true,
        data: result.data,
    };
};


/*
|--------------------------------------------------------------------------
| Inferred Types
|--------------------------------------------------------------------------
*/

export type OwnerLoginValidatedInput =
    z.infer<typeof ownerLoginSchema>;

export type OwnerSecretVerificationValidatedInput =
    z.infer<
        typeof ownerSecretVerificationSchema
    >;

export type OwnerSecretVerificationWithSessionValidatedInput =
    z.infer<
        typeof ownerSecretVerificationWithSessionSchema
    >;

export type OwnerLogoutValidatedInput =
    z.infer<typeof ownerLogoutSchema>;

import mongoose, { Types } from "mongoose";

import { ApiError } from "../../utils/ApiError";
import ProductModel from "./product.model";

import type {
  ProductInput,
  ProductListQuery,
  ProductStatus,
  ProductUpdateInput,
} from "./product.types";

const escapeRegex = (value: string): string =>
  value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

const normalizeSlug = (value: string): string =>
  value.normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .trim()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 200);

const normalizeSku = (value?: string): string | undefined =>
  value?.trim().toUpperCase() || undefined;

const normalizeBarcode = (value?: string): string | undefined =>
  value?.trim() || undefined;

function throwDuplicateKey(error: unknown): never {
  const mongoError = error as {
    code?: number;
    keyPattern?: Record<string, unknown>;
  };

  if (mongoError?.code === 11000) {
    const field = Object.keys(mongoError.keyPattern ?? {})[0];

    throw ApiError.conflict(
      `A product with this ${field || "unique field"} already exists.`,
      { code: "DUPLICATE_PRODUCT_FIELD" },
    );
  }

  throw error;
}

function validatePriceRelationship(
  price?: number,
  compareAtPrice?: number,
): void {
  if (
    price !== undefined &&
    compareAtPrice !== undefined &&
    compareAtPrice <= price
  ) {
    throw ApiError.badRequest(
      "compareAtPrice must be greater than price.",
    );
  }
}

function getModel(name: string) {
  try {
    return mongoose.model(name);
  } catch {
    throw ApiError.internal(
      `The ${name} model has not been registered.`,
    );
  }
}

async function assertReferencesExist(
  input: Partial<ProductInput>,
): Promise<void> {
  if (input.categoryId) {
    const category = await getModel("Category")
      .exists({ _id: input.categoryId });

    if (!category) {
      throw ApiError.notFound("Category does not exist.");
    }
  }

  if (input.subcategoryId) {
    const subcategory = await getModel("Subcategory")
      .findById(input.subcategoryId)
      .select("categoryId")
      .lean();

    if (!subcategory) {
      throw ApiError.notFound("Subcategory does not exist.");
    }

    const subcategoryCategoryId = (
      subcategory as unknown as {
        categoryId?: Types.ObjectId;
      }
    ).categoryId;

    if (
      input.categoryId &&
      String(subcategoryCategoryId) !== String(input.categoryId)
    ) {
      throw ApiError.badRequest(
        "Subcategory does not belong to the selected category.",
      );
    }
  }

  if (input.brandId) {
    const brand = await getModel("Brand")
      .exists({ _id: input.brandId });

    if (!brand) {
      throw ApiError.notFound("Brand does not exist.");
    }
  }

  if (input.collectionIds?.length) {
    const uniqueIds = [...new Set(input.collectionIds)];

    const count = await getModel("Collection")
      .countDocuments({ _id: { $in: uniqueIds } });

    if (count !== uniqueIds.length) {
      throw ApiError.badRequest(
        "One or more collections do not exist.",
      );
    }
  }
}

function validateProductRules(
  input: Partial<ProductInput>,
): void {
  if (
    input.type === "DIGITAL" &&
    input.requiresShipping === true
  ) {
    throw ApiError.badRequest(
      "Digital products cannot require shipping.",
    );
  }
}

export async function createProduct(
  input: ProductInput,
  actorId?: string,
) {
  const name = input.name.trim();
  const slug = normalizeSlug(input.slug || name);

  if (!slug) {
    throw ApiError.badRequest("A valid product slug is required.");
  }

  validatePriceRelationship(input.price, input.compareAtPrice);
  validateProductRules(input);
  await assertReferencesExist(input);

  const payload: Record<string, unknown> = {
    ...input,
    name,
    slug,
    sku: normalizeSku(input.sku),
    barcode: normalizeBarcode(input.barcode),
    tags: [...new Set((input.tags ?? []).map((tag) => tag.trim()))],
    collectionIds: input.collectionIds ?? [],
  };

  if (actorId && Types.ObjectId.isValid(actorId)) {
    payload.createdBy = new Types.ObjectId(actorId);
    payload.updatedBy = new Types.ObjectId(actorId);
  }

  try {
    return await ProductModel.create(payload);
  } catch (error) {
    throwDuplicateKey(error);
  }
}

export async function getProductById(
  id: string,
  options: {
    includeArchived?: boolean;
    includeCostPrice?: boolean;
  } = {},
) {
  if (!Types.ObjectId.isValid(id)) {
    throw ApiError.badRequest("Invalid product ID.");
  }

  const query = ProductModel.findById(id);

  if (!options.includeArchived) {
    query.where({ status: { $ne: "ARCHIVED" } });
  }

  if (options.includeCostPrice) {
    query.select("+costPrice");
  }

  const product = await query;

  if (!product) {
    throw ApiError.notFound("Product not found.");
  }

  return product;
}

export async function getProductBySlug(
  slug: string,
  options: { includeArchived?: boolean } = {},
) {
  const query = ProductModel.findOne({
    slug: normalizeSlug(slug),
    ...(options.includeArchived ? {} : { status: "ACTIVE" }),
  });

  const product = await query;

  if (!product) {
    throw ApiError.notFound("Product not found.");
  }

  return product;
}

export async function listProducts(
  query: ProductListQuery,
  options: { publicOnly?: boolean } = {},
) {
  const page = query.page ?? 1;
  const limit = query.limit ?? 20;

  // A flexible MongoDB filter avoids relying on an unavailable
  // Mongoose FilterQuery export in this project.
  const filter: Record<string, any> = {};

  if (options.publicOnly) {
    filter.status = "ACTIVE";
  } else if (query.status) {
    filter.status = query.status;
  } else {
    filter.status = { $ne: "ARCHIVED" };
  }

  if (query.type) filter.type = query.type;
  if (query.categoryId) filter.categoryId = query.categoryId;
  if (query.subcategoryId) filter.subcategoryId = query.subcategoryId;
  if (query.brandId) filter.brandId = query.brandId;

  if (query.featured !== undefined) {
    filter.featured = query.featured;
  }

  if (
    query.minPrice !== undefined ||
    query.maxPrice !== undefined
  ) {
    filter.price = {
      ...(query.minPrice !== undefined && { $gte: query.minPrice }),
      ...(query.maxPrice !== undefined && { $lte: query.maxPrice }),
    };
  }

  if (query.inStock === true) {
    filter.$or = [
      { trackInventory: false },
      { stockQuantity: { $gt: 0 } },
      { inventoryPolicy: "CONTINUE" },
    ];
  } else if (query.inStock === false) {
    filter.trackInventory = true;
    filter.stockQuantity = { $lte: 0 };
    filter.inventoryPolicy = "DENY";
  }

  if (query.search?.trim()) {
    const safeSearch = escapeRegex(query.search.trim());

    filter.$and = [
      {
        $or: [
          { name: { $regex: safeSearch, $options: "i" } },
          { sku: { $regex: safeSearch, $options: "i" } },
          { barcode: { $regex: safeSearch, $options: "i" } },
          { shortDescription: { $regex: safeSearch, $options: "i" } },
        ],
      },
    ];
  }

  const allowedSortFields = [
    "createdAt",
    "updatedAt",
    "name",
    "price",
    "sortOrder",
  ];

  const sortBy = allowedSortFields.includes(query.sortBy ?? "")
    ? query.sortBy!
    : "createdAt";

  const sortDirection = query.sortOrder === "asc" ? 1 : -1;
  const sort: Record<string, 1 | -1> = {
    [sortBy]: sortDirection,
    _id: -1,
  };

  const [items, total] = await Promise.all([
    ProductModel.find(filter)
      .sort(sort)
      .skip((page - 1) * limit)
      .limit(limit)
      .populate("categoryId", "name slug")
      .populate("subcategoryId", "name slug")
      .populate("brandId", "name slug")
      .lean(),

    ProductModel.countDocuments(filter),
  ]);

  const totalPages = Math.ceil(total / limit);

  return {
    items,
    pagination: {
      page,
      limit,
      total,
      totalPages,
      hasNextPage: page < totalPages,
      hasPreviousPage: page > 1,
    },
  };
}

export async function updateProduct(
  id: string,
  input: ProductUpdateInput,
  actorId?: string,
) {
  const product = await getProductById(id, {
    includeArchived: true,
  });

  if (product.status === "ARCHIVED") {
    throw ApiError.conflict("Archived products cannot be edited.");
  }

  const nextPrice = input.price ?? product.price;
  const nextCompareAt =
    input.compareAtPrice !== undefined
      ? input.compareAtPrice
      : product.compareAtPrice;

  validatePriceRelationship(nextPrice, nextCompareAt);

  validateProductRules({
    type: input.type ?? product.type,
    requiresShipping:
      input.requiresShipping ?? product.requiresShipping,
  });

  const nextCategoryId =
    input.categoryId ?? String(product.categoryId);

  const nextSubcategoryId =
    input.subcategoryId !== undefined
      ? input.subcategoryId
      : product.subcategoryId
        ? String(product.subcategoryId)
        : undefined;

  const nextBrandId =
    input.brandId !== undefined
      ? input.brandId
      : product.brandId
        ? String(product.brandId)
        : undefined;

  await assertReferencesExist({
    categoryId: nextCategoryId,
    subcategoryId: nextSubcategoryId,
    brandId: nextBrandId,
    collectionIds: input.collectionIds,
  });

  const updates: Record<string, unknown> = { ...input };

  if (input.name && input.slug === undefined) {
    updates.slug = normalizeSlug(input.name);
  } else if (input.slug !== undefined) {
    updates.slug = normalizeSlug(input.slug);
  }

  if (updates.slug === "") {
    throw ApiError.badRequest("A valid product slug is required.");
  }

  if (input.sku !== undefined) {
    updates.sku = normalizeSku(input.sku);
  }

  if (input.barcode !== undefined) {
    updates.barcode = normalizeBarcode(input.barcode);
  }

  if (input.tags !== undefined) {
    updates.tags = [...new Set(input.tags.map((tag) => tag.trim()))];
  }

  if (input.collectionIds !== undefined) {
    updates.collectionIds = input.collectionIds;
  }

  if (actorId && Types.ObjectId.isValid(actorId)) {
    updates.updatedBy = new Types.ObjectId(actorId);
  }

  try {
    Object.assign(product, updates);
    await product.save();
    return product;
  } catch (error) {
    throwDuplicateKey(error);
  }
}

export async function updateProductStatus(
  id: string,
  status: ProductStatus,
  actorId?: string,
) {
  const product = await getProductById(id, {
    includeArchived: true,
  });

  if (product.status === "ARCHIVED" && status !== "ARCHIVED") {
    throw ApiError.conflict(
      "Archived products cannot be reactivated through status update.",
    );
  }

  product.status = status;

  if (actorId && Types.ObjectId.isValid(actorId)) {
    product.updatedBy = new Types.ObjectId(actorId);
  }

  if (status === "ARCHIVED") {
    product.archivedAt = new Date();
  } else {
    product.archivedAt = undefined;
  }

  await product.save();
  return product;
}

export async function archiveProduct(
  id: string,
  actorId?: string,
) {
  return updateProductStatus(id, "ARCHIVED", actorId);
}

import {
    Types,
} from "mongoose";

import {
    RiderEarning,
    RIDER_EARNING_STATUSES,
    type RiderEarningStatus,
    type RiderEarningType,
} from "./riderEarning.model";

import type {
    RiderEarningData,
    RiderEarningListResult,
    RiderEarningSummary,
} from "./riderEarning.types";

import {
    Rider,
} from "../riders/rider.model";

import {
    ApiError,
} from "../../utils/ApiError";


/*
|--------------------------------------------------------------------------
| Types
|--------------------------------------------------------------------------
*/

export interface CreateRiderEarningServiceInput {
    readonly riderId: string;
    readonly orderId?: string;
    readonly type: RiderEarningType;
    readonly amount: number;
    readonly currency?: string;
    readonly description?: string;
    readonly earningDate?: Date;
    readonly notes?: string;
    readonly createdBy?: string;
}

export interface UpdateRiderEarningServiceInput {
    readonly type?: RiderEarningType;
    readonly amount?: number;
    readonly currency?: string;
    readonly description?: string;
    readonly earningDate?: Date;
    readonly notes?: string;
    readonly updatedBy?: string;
}

export interface UpdateRiderEarningStatusServiceInput {
    readonly status: RiderEarningStatus;
    readonly reason?: string;
    readonly notes?: string;
    readonly updatedBy?: string;
}

export interface RiderEarningListOptions {
    readonly page?: number;
    readonly limit?: number;
    readonly status?: RiderEarningStatus;
    readonly type?: RiderEarningType;
    readonly riderId?: string;
    readonly orderId?: string;
    readonly currency?: string;
    readonly from?: Date;
    readonly to?: Date;
}


/*
|--------------------------------------------------------------------------
| Constants
|--------------------------------------------------------------------------
*/

const DEFAULT_PAGE = 1;
const DEFAULT_LIMIT = 20;
const MAX_LIMIT = 100;


/*
|--------------------------------------------------------------------------
| Helpers
|--------------------------------------------------------------------------
*/

const ensureObjectId = (
    value: string,
    fieldName: string,
): Types.ObjectId => {
    if (!Types.ObjectId.isValid(value)) {
        throw ApiError.badRequest(
            `Invalid ${fieldName}.`,
        );
    }

    return new Types.ObjectId(value);
};


const ensureRiderExists = async (
    riderId: string,
): Promise<void> => {
    const riderObjectId = ensureObjectId(
        riderId,
        "rider ID",
    );

    const rider = await Rider
        .findById(riderObjectId)
        .select("_id status")
        .lean();

    if (!rider) {
        throw ApiError.notFound(
            "Rider not found.",
        );
    }

    if (rider.status === "TERMINATED") {
        throw ApiError.badRequest(
            "Cannot create earnings for a terminated rider.",
        );
    }
};


const normalizeCurrency = (
    currency?: string,
): string => {
    return (
        currency ??
        "SAR"
    )
        .trim()
        .toUpperCase();
};


const getAllowedStatusTransitions = (
    status: RiderEarningStatus,
): readonly RiderEarningStatus[] => {
    switch (status) {
        case "PENDING":
            return [
                "APPROVED",
                "CANCELLED",
            ];

        case "APPROVED":
            return [
                "PAID",
                "CANCELLED",
            ];

        case "PAID":
            return [];

        case "CANCELLED":
            return [];

        default:
            return [];
    }
};


const serializeEarning = (
    earning: RiderEarningData,
): RiderEarningData => {
    return earning;
};


/*
|--------------------------------------------------------------------------
| Create
|--------------------------------------------------------------------------
*/

export const createRiderEarning = async (
    input: CreateRiderEarningServiceInput,
): Promise<RiderEarningData> => {
    await ensureRiderExists(
        input.riderId,
    );

    const riderId = ensureObjectId(
        input.riderId,
        "rider ID",
    );

    const orderId = input.orderId
        ? ensureObjectId(
            input.orderId,
            "order ID",
        )
        : undefined;

    const createdBy = input.createdBy
        ? ensureObjectId(
            input.createdBy,
            "creator ID",
        )
        : undefined;

    const earning = await RiderEarning.create({
        riderId,
        orderId,
        type: input.type,
        amount: input.amount,
        currency: normalizeCurrency(
            input.currency,
        ),
        description:
            input.description?.trim(),
        earningDate:
            input.earningDate ??
            new Date(),
        notes: input.notes?.trim(),
        createdBy,
        updatedBy: createdBy,
    });

    return earning.toObject() as RiderEarningData;
};


/*
|--------------------------------------------------------------------------
| Get By ID
|--------------------------------------------------------------------------
*/

export const getRiderEarningById = async (
    earningId: string,
): Promise<RiderEarningData> => {
    const id = ensureObjectId(
        earningId,
        "earning ID",
    );

    const earning = await RiderEarning
        .findById(id)
        .lean();

    if (!earning) {
        throw ApiError.notFound(
            "Rider earning not found.",
        );
    }

    return earning as RiderEarningData;
};


/*
|--------------------------------------------------------------------------
| Get By Rider
|--------------------------------------------------------------------------
*/

export const getRiderEarningsByRider = async (
    riderId: string,
    options: RiderEarningListOptions = {},
): Promise<RiderEarningListResult> => {
    ensureObjectId(
        riderId,
        "rider ID",
    );

    return listRiderEarnings({
        ...options,
        riderId,
    });
};


/*
|--------------------------------------------------------------------------
| List
|--------------------------------------------------------------------------
*/

export const listRiderEarnings = async (
    options: RiderEarningListOptions = {},
): Promise<RiderEarningListResult> => {
    const page = Math.max(
        DEFAULT_PAGE,
        options.page ?? DEFAULT_PAGE,
    );

    const limit = Math.min(
        MAX_LIMIT,
        Math.max(
            1,
            options.limit ?? DEFAULT_LIMIT,
        ),
    );

    const skip = (page - 1) * limit;

    const filter: Record<string, unknown> = {};

    if (options.status) {
        filter.status = options.status;
    }

    if (options.type) {
        filter.type = options.type;
    }

    if (options.riderId) {
        filter.riderId = ensureObjectId(
            options.riderId,
            "rider ID",
        );
    }

    if (options.orderId) {
        filter.orderId = ensureObjectId(
            options.orderId,
            "order ID",
        );
    }

    if (options.currency) {
        filter.currency =
            normalizeCurrency(
                options.currency,
            );
    }

    if (options.from || options.to) {
        filter.earningDate = {
            ...(options.from
                ? {
                    $gte: options.from,
                }
                : {}),

            ...(options.to
                ? {
                    $lte: options.to,
                }
                : {}),
        };
    }

    const [
        earnings,
        total,
    ] = await Promise.all([
        RiderEarning
            .find(filter)
            .sort({
                earningDate: -1,
                createdAt: -1,
            })
            .skip(skip)
            .limit(limit)
            .lean(),

        RiderEarning.countDocuments(
            filter,
        ),
    ]);

    const totalPages =
        Math.ceil(total / limit);

    return {
        earnings:
            earnings as RiderEarningData[],

        pagination: {
            page,
            limit,
            total,
            totalPages,

            hasNextPage:
                page < totalPages,

            hasPreviousPage:
                page > 1,
        },
    };
};


/*
|--------------------------------------------------------------------------
| Update
|--------------------------------------------------------------------------
*/

export const updateRiderEarning = async (
    earningId: string,
    input: UpdateRiderEarningServiceInput,
): Promise<RiderEarningData> => {
    const id = ensureObjectId(
        earningId,
        "earning ID",
    );

    const earning =
        await RiderEarning.findById(id);

    if (!earning) {
        throw ApiError.notFound(
            "Rider earning not found.",
        );
    }

    if (
        earning.status === "PAID" ||
        earning.status === "CANCELLED"
    ) {
        throw ApiError.badRequest(
            `Cannot update a ${earning.status.toLowerCase()} earning.`,
        );
    }

    if (input.type !== undefined) {
        earning.type = input.type;
    }

    if (input.amount !== undefined) {
        earning.amount = input.amount;
    }

    if (input.currency !== undefined) {
        earning.currency =
            normalizeCurrency(
                input.currency,
            );
    }

    if (input.description !== undefined) {
        earning.description =
            input.description.trim();
    }

    if (input.earningDate !== undefined) {
        earning.earningDate =
            input.earningDate;
    }

    if (input.notes !== undefined) {
        earning.notes =
            input.notes.trim();
    }

    if (input.updatedBy) {
        earning.updatedBy =
            ensureObjectId(
                input.updatedBy,
                "updater ID",
            );
    }

    await earning.save();

    return earning.toObject() as RiderEarningData;
};


/*
|--------------------------------------------------------------------------
| Status Update
|--------------------------------------------------------------------------
*/

export const updateRiderEarningStatus = async (
    earningId: string,
    input: UpdateRiderEarningStatusServiceInput,
): Promise<RiderEarningData> => {
    const id = ensureObjectId(
        earningId,
        "earning ID",
    );

    const earning =
        await RiderEarning.findById(id);

    if (!earning) {
        throw ApiError.notFound(
            "Rider earning not found.",
        );
    }

    if (
        !RIDER_EARNING_STATUSES.includes(
            input.status,
        )
    ) {
        throw ApiError.badRequest(
            "Invalid rider earning status.",
        );
    }

    const allowedTransitions =
        getAllowedStatusTransitions(
            earning.status,
        );

    if (
        !allowedTransitions.includes(
            input.status,
        )
    ) {
        throw ApiError.badRequest(
            `Cannot change earning status from ${earning.status} to ${input.status}.`,
        );
    }

    const now = new Date();

    earning.status = input.status;

    if (input.notes !== undefined) {
        earning.notes =
            input.notes.trim();
    }

    if (input.updatedBy) {
        earning.updatedBy =
            ensureObjectId(
                input.updatedBy,
                "updater ID",
            );
    }

    if (input.status === "APPROVED") {
        earning.approvedAt = now;

        if (input.updatedBy) {
            earning.approvedBy =
                ensureObjectId(
                    input.updatedBy,
                    "approver ID",
                );
        }
    }

    if (input.status === "PAID") {
        earning.paidAt = now;

        if (input.updatedBy) {
            earning.paidBy =
                ensureObjectId(
                    input.updatedBy,
                    "payer ID",
                );
        }
    }

    if (input.status === "CANCELLED") {
        earning.cancelledAt = now;

        if (input.updatedBy) {
            earning.cancelledBy =
                ensureObjectId(
                    input.updatedBy,
                    "canceller ID",
                );
        }

        earning.cancellationReason =
            input.reason?.trim();
    }

    await earning.save();

    return earning.toObject() as RiderEarningData;
};


