/*
|--------------------------------------------------------------------------
| Rider Summary
|--------------------------------------------------------------------------
*/

export const getRiderEarningSummary = async (
    riderId: string,
    currency = "SAR",
): Promise<RiderEarningSummary> => {
    const riderObjectId =
        ensureObjectId(
            riderId,
            "rider ID",
        );

    const normalizedCurrency =
        normalizeCurrency(currency);

    const summary =
        await RiderEarning.aggregate([
            {
                $match: {
                    riderId:
                        riderObjectId,

                    currency:
                        normalizedCurrency,
                },
            },

            {
                $group: {
                    _id: "$status",

                    total: {
                        $sum: "$amount",
                    },
                },
            },
        ]);

    const result: RiderEarningSummary = {
        totalEarnings: 0,
        pendingEarnings: 0,
        approvedEarnings: 0,
        paidEarnings: 0,
        cancelledEarnings: 0,
        currency:
            normalizedCurrency,
    };

    for (const item of summary) {
        const amount =
            Number(item.total) || 0;

        switch (item._id) {
            case "PENDING":
                result.pendingEarnings += amount;
                break;

            case "APPROVED":
                result.approvedEarnings += amount;
                break;

            case "PAID":
                result.paidEarnings += amount;
                break;

            case "CANCELLED":
                result.cancelledEarnings += amount;
                break;
        }

        result.totalEarnings += amount;
    }

    return result;
};


