| Role Response
|--------------------------------------------------------------------------
*/

type RoleResponse = Record<
    string,
    unknown
> & {
    id: string;
};


/*
|--------------------------------------------------------------------------
| Serialize Role
|--------------------------------------------------------------------------
|
| Converts the Mongoose `_id` field into the public API `id` field.
|
|--------------------------------------------------------------------------
*/

const serializeRole = (
    role: {
        _id: unknown;
        toObject: () => Record<
            string,
            unknown
        >;
    }
): RoleResponse => {

    const plainRole =
        role.toObject();

    const mongoId =
        plainRole._id;

    if (
        mongoId === undefined ||
        mongoId === null
    ) {
        throw ApiError.internal(
            "Role identifier is missing.",
            {
                code:
                    "ROLE_IDENTIFIER_MISSING",
            }
        );
    }

    const {
        _id: _ignoredId,
        ...rest
    } = plainRole;

    return {
        ...rest,

        id:
            String(
                mongoId
            ),
    };
};


