/*
|--------------------------------------------------------------------------
| Helpers
|--------------------------------------------------------------------------
*/

const validateObjectId = (
    value: string,
    fieldName: string,
): Types.ObjectId => {
    if (!Types.ObjectId.isValid(value)) {
        throw ApiError.badRequest(
            `Invalid ${fieldName}.`,
        );
    }

    return new Types.ObjectId(value);
};

const normalizeEmail = (
    email: string,
): string => email.trim().toLowerCase();

const normalizeSellerCode = (
    sellerCode: string,
): string => sellerCode.trim().toUpperCase();

/*
|--------------------------------------------------------------------------
| Status Transitions
|--------------------------------------------------------------------------
*/

const SELLER_STATUS_TRANSITIONS: Record<
    SellerStatus,
    readonly SellerStatus[]
> = {
    PENDING: [
        "ACTIVE",
        "REJECTED",
        "INACTIVE",
    ],

    ACTIVE: [
        "INACTIVE",
        "SUSPENDED",
    ],

    INACTIVE: [
        "ACTIVE",
        "SUSPENDED",
    ],

    SUSPENDED: [
        "ACTIVE",
        "INACTIVE",
    ],

    REJECTED: [],
};

const canTransitionSellerStatus = (
    currentStatus: SellerStatus,
    nextStatus: SellerStatus,
): boolean => {
    return SELLER_STATUS_TRANSITIONS[
        currentStatus
    ].includes(nextStatus);
};

/*
|--------------------------------------------------------------------------
| Create Seller
|--------------------------------------------------------------------------
*/

export const createSeller = async (
    input: CreateSellerInput,
    actorId?: string,
) => {
    const userId = validateObjectId(
        input.userId,
        "userId",
    );

    const normalizedEmail =
        normalizeEmail(input.email);

    const normalizedSellerCode =
        normalizeSellerCode(
            input.sellerCode,
        );

    const existingSellerByUser =
        await Seller.findOne({
            userId,
        });

    if (existingSellerByUser) {
        throw ApiError.conflict(
            "A seller already exists for this user.",
        );
    }

    const existingSellerByCode =
        await Seller.findOne({
            sellerCode: normalizedSellerCode,
        });

    if (existingSellerByCode) {
        throw ApiError.conflict(
            "Seller code already exists.",
        );
    }

    const existingSellerByEmail =
        await Seller.findOne({
            email: normalizedEmail,
        });

    if (existingSellerByEmail) {
        throw ApiError.conflict(
            "Seller email already exists.",
        );
    }

    const actorObjectId = actorId
        ? validateObjectId(
              actorId,
              "actorId",
          )
        : undefined;

    const seller =
        await Seller.create({
            userId,

            sellerCode:
                normalizedSellerCode,

            type: input.type,

            businessName:
                input.businessName,

            legalName:
                input.legalName,

            email:
                normalizedEmail,

            phone:
                input.phone,

            taxNumber:
                input.taxNumber,

            registrationNumber:
                input.registrationNumber,

            description:
                input.description,

            logoUrl:
                input.logoUrl,

            website:
                input.website,

            status: "PENDING",

            notes:
                input.notes,

            createdBy:
                actorObjectId,

            updatedBy:
                actorObjectId,
        });

    return seller;
};

