/*
|--------------------------------------------------------------------------
| Safe User Response
|--------------------------------------------------------------------------
|
| Password hash must never be exposed through an API response.
|
|--------------------------------------------------------------------------
*/

const sanitizeUser = (
    user: any
) => {
    const userObject =
        typeof user.toObject === "function"
            ? user.toObject()
            : { ...user };

    delete userObject.password;

    return userObject;
};


