| Create User
|--------------------------------------------------------------------------
*/

export const createUserController =
    asyncHandler(
        async (
            req: Request,
            res: Response
        ): Promise<void> => {

            const input =
                req.body as CreateUserInput;

            const user =
                await createUser(
                    input
                );

            res.status(201).json({
                success: true,

                message:
                    "User created successfully.",

                data: {
                    user:
                        sanitizeUser(
                            user
                        ),
                },
            });
        }
    );


